--
-- Table structure for table `jenis_penyakit`
--

CREATE TABLE `jenis_penyakit` (
  `id_penyakit` int NOT NULL,
  `nama_penyakit` varchar(100) DEFAULT NULL,
  `penyebab` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `gejala` text,
  `cara_pengendalian` text,
  `gambar_ilustrasi` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Dumping data for table `jenis_penyakit`
--

INSERT INTO `jenis_penyakit` (`id_penyakit`, `nama_penyakit`, `penyebab`, `gejala`, `cara_pengendalian`, `gambar_ilustrasi`) VALUES
(1, 'Busuk Pangkal Batang (Basal Stem Rot)', 'Penyakit busuk pangkal batang disebabkan oleh jamur Ganoderma boninense, patogen paling merusak dalam industri kelapa sawit. Jamur ini bersifat berada dalam tanah dan dapat bertahan selama puluhan tahun dalam bentuk spora atau miselium. Infeksi dimulai ketika spora jamur melakukan kontak dengan akar atau pangkal batang tanaman melalui luka atau celah alami pada jaringan. Ganoderma memiliki enzim yang dapat merusak lignin dan selulosa pada dinding sel tanaman, menyebabkan pembusukan jaringan secara menyeluruh.\r\n\r\nJamur menyebar melalui kontak akar antara tanaman sakit dan sehat, spora yang terbawa angin atau air, serta melalui sisa tanaman terinfeksi. Faktor risiko meliputi tanah yang pernah ditanami sawit tanpa perlakuan memadai, drainase buruk, pelukaan pada akar atau batang, penggunaan bahan organik terinfeksi sebagai mulsa, umur tanaman tua, dan genetik material tanam yang mudah terserang. Tanah dengan genangan air menciptakan tekanan pada akar yang memudahkan penetrasi patogen. Kekurangan nutrisi terutama Kalium dan Magnesium melemahkan kekuatan tanaman. Nematoda parasit dan hama perusak akar menciptakan luka sebagai pintu masuk infeksi. Periode inkubasi sangat panjang 1-3 tahun bahkan bisa 5-7 tahun sebelum gejala luar terlihat jelas, menyulitkan deteksi dini dan penanganan.', 'Gejala awal berupa perubahan warna daun bagian bawah menjadi pucat atau kekuningan. Daun tua mengering sebelum waktunya dan pelepah mudah patah karena jaringan dalam melemah. Gejala khas adalah munculnya tubuh buah jamur berbentuk kipas berwarna coklat kemerahan dengan permukaan mengkilap di pangkal batang atau akar permukaan, ukuran 5-50 cm diameter. Pertumbuhan sangat terhambat, produksi Tandan Buah Segar menurun 50-70%, tandan berukuran kecil dengan buah sedikit. Jika batang dipotong, terlihat jaringan dalam berwarna coklat kehitaman dengan tekstur lunak dan bau busuk.\r\n\r\nPada tahap lanjut, hanya tersisa beberapa pelepah hijau di pucuk seperti payung terbalik, mahkota sangat sempit dan tegak. Akar samping membusuk sangat parah sehingga tanaman mudah roboh saat angin kencang. Sistem akar menunjukkan pembusukan masif dengan akar berwarna coklat hitam, mudah patah. Ujung akar putih yang sehat sangat sedikit atau tidak ada. Laju pertumbuhan menurun drastis, produksi daun hanya 12-16 helai per tahun dari normal 20-24 helai. Tajuk menjadi sangat sempit dengan kurang dari 8-12 pelepah menciptakan penampilan seperti ujung pensil. Tanaman terinfeksi berat biasanya mati dalam 2-3 tahun setelah gejala jelas terlihat.', 'Pengendalian sangat menantang karena belum ada metode penyembuhan yang efektif. Strategi harus menyeluruh dengan penekanan pada pencegahan dan deteksi dini. Pengelolaan sebelum tanam: bongkar total tanaman sakit beserta akar menggunakan alat berat hingga kedalaman 1-1.5 meter. Sisa tanaman dibakar atau dikubur jauh dari area tanam. Lahan dibiarkan istirahat 6-12 bulan dengan tanaman penutup tanah bukan inang seperti Mucuna bracteata. Perlakuan lubang tanam dengan Trichoderma harzianum 50-100 gram per lubang untuk membentuk populasi antagonis.\r\n\r\nPengelolaan setelah tanam: sanitasi ketat dengan membuang semua sisa tanaman terinfeksi. Alat dan peralatan dari area terinfeksi harus dibersihkan dan didisinfeksi. Pengawasan rutin setiap 3-6 bulan untuk mengidentifikasi tanaman bergejala. Pembongkaran tanaman dengan gejala sedang hingga berat untuk menghilangkan sumber penular. Parit isolasi sedalam 1-1.5 meter di sekeliling tanaman terinfeksi untuk memutus kontak akar. Perlakuan kimia dengan hexaconazole 5-10 ml per pohon setiap 3-6 bulan untuk tanaman dengan gejala ringan. Pemupukan berimbang dengan penekanan pada Kalium dan Magnesium untuk memperkuat dinding sel. Perbaikan drainase untuk mencegah genangan air. Penggunaan bibit dari sumber terpercaya dan material dengan ketahanan lebih baik. Pemantauan kesehatan tanaman rutin dengan mencatat perkembangan gejala.', '85658699f6d026444dd2e8f7a098953f.jpeg'),
(2, 'Busuk Kuncup', 'Penyakit busuk kuncup disebabkan oleh jamur Phytophthora palmivora yang memerlukan kondisi lembab tinggi untuk perkembangan dan infeksi. Patogen ini tersebar luas di daerah tropis dengan curah hujan tinggi. Phytophthora palmivora menghasilkan spora bergerak yang dapat berenang dalam lapisan air menuju titik tumbuh tanaman, terutama saat hujan lebat atau genangan air di pucuk.\r\n\r\nInfeksi dimulai ketika spora bergerak menembus jaringan muda pada kuncup atau daun tombak, kemudian berkembang biak cepat merusak jaringan sel menyebabkan pembusukan. Jamur menghasilkan enzim yang menghancurkan dinding sel tanaman. Faktor pemicu meliputi tanaman muda (Tanaman Belum Menghasilkan 1-5 tahun) dengan jaringan titik tumbuh lunak dan rentan, curah hujan sangat tinggi (lebih dari 3000 mm per tahun), drainase buruk, kekurangan Kalium dan Boron, pelukaan mekanis pada pucuk, kepadatan tanaman tinggi, dan sumber penular dari tanaman terinfeksi. Penyakit menyebar melalui percikan air hujan, alat pemeliharaan terkontaminasi, dan pekerja tanpa sanitasi memadai.', 'Gejala awal berupa perubahan warna daun tombak dari hijau segar menjadi pucat kekuningan. Daun tombak gagal membuka sempurna, tetap tergulung, dan mudah dicabut. Jaringan dalam membusuk berwarna coklat dengan tekstur lunak dan berair, mengeluarkan bau busuk menyengat. Seluruh titik tumbuh membusuk total sehingga tanaman kehilangan kemampuan menghasilkan daun baru. Kadang keluar cairan coklat kental dari pangkal daun yang mengalir membasahi batang.\r\n\r\nTanaman dapat bertahan hidup dengan menghasilkan tunas samping namun pertumbuhan tidak normal dengan beberapa mahkota dan produktivitas sangat rendah. Pada fase sangat muda (bibit atau Tanaman Belum Menghasilkan 1-2 tahun), tanaman mati total dalam 2-4 minggu setelah gejala muncul. Pada tanaman lebih dewasa (Tanaman Belum Menghasilkan 3-5 tahun), dapat bertahan lebih lama tetapi pertumbuhan sangat terhambat. Serangan berat menyebabkan tingkat kematian 30-50% dengan kerugian ekonomi sangat besar. Gejala harus dibedakan dengan kerusakan mekanis atau serangan kumbang tanduk.', 'Perbaikan drainase adalah prioritas utama untuk menghindari genangan air. Buat saluran drainase memadai dengan jarak 50-100 meter, kedalaman minimal 80-100 cm pada lahan datar. Aplikasi fungisida pencegahan sangat penting terutama saat musim hujan. Fungisida metalaxyl-M atau metalaxyl 2-3 gram per liter disemprotkan ke pucuk atau disiram ke titik tumbuh 250-500 ml per tanaman. Alternatif fosetyl-Al 2.5-3 gram per liter yang bersifat sistemik. Aplikasi setiap 2-4 minggu selama periode risiko tinggi.\r\n\r\nUntuk tanaman dengan gejala awal, perlakuan segera dengan fungisida sistemik masih bisa menyelamatkan. Pemangkasan jaringan busuk dengan hati-hati, alat disterilkan dengan alkohol 70% atau natrium hipoklorit 1% setiap setelah digunakan. Jaringan terinfeksi dikumpulkan dan dibakar. Pemupukan Kalium 2-3 kg KCl per pohon per tahun untuk tanaman muda meningkatkan ketebalan dinding sel. Aplikasi Boron 25-50 gram boraks per pohon per tahun untuk pembentukan dinding sel dan penguatan jaringan. Sanitasi kebun dengan membuang tanaman mati atau terinfeksi berat. Pengurangan kelembaban dengan pengaturan populasi tidak terlalu padat, pemangkasan pelepah tua, dan pengendalian gulma. Pemantauan rutin setiap 1-2 minggu saat musim hujan untuk deteksi dini.', 'e7498fc9c3f337e5b6dc0ff2596a75a9.jpeg'),
(3, 'Garis Kuning', 'Penyakit garis kuning masih menjadi misteri karena penyebab pasti belum terungkap. Beberapa teori berkembang: pertama, infeksi oleh organisme mirip mikoplasma atau fitoplasma yang menyerang sistem pembuluh menyebabkan gangguan perpindahan nutrisi, dapat ditularkan melalui serangga penular. Kedua, kekurangan nutrisi kronis terutama Nitrogen dan Magnesium yang parah menyebabkan gejala mirip garis kuning. Analisis jaringan tanaman sakit menunjukkan kadar Nitrogen dan Magnesium sangat rendah. Ketiga, kombinasi faktor nutrisi dan patogen dimana kekurangan nutrisi melemahkan tanaman sehingga rentan terhadap patogen oportunistik. Keempat, faktor genetik dimana beberapa material sawit memiliki kecenderungan genetik terhadap garis kuning.\r\n\r\nPenyakit lebih banyak pada lahan marjinal seperti tanah ultisol atau oksisol yang miskin hara. Tanah dengan pH sangat rendah (kurang dari 4.5) menyebabkan ketersediaan Magnesium dan Kalsium sangat terbatas. Lahan dengan drainase sangat buruk atau sangat kering, perkebunan dengan sejarah pemupukan tidak memadai. Pemadatan tanah menghambat perkembangan akar, nematoda parasit merusak sistem perakaran sehingga penyerapan nutrisi terganggu, tekanan lingkungan berkepanjangan. Penyakit muncul secara sporadis pada tanaman individual atau kelompok kecil.', 'Gejala khas adalah garis-garis berwarna kuning cerah hingga pucat sejajar dengan tulang daun, sementara area di sekitar tulang daun utama tetap hijau menciptakan kontras khas. Gejala dimulai pada daun tua di bagian bawah mahkota, kemudian menyebar ke daun muda. Dalam kasus berat, hampir seluruh daun menunjukkan garis dan tanaman sangat pucat. Lebar garis beberapa milimeter hingga 2-3 cm, panjangnya sepanjang helaian daun.\r\n\r\nTanaman terserang menunjukkan pertumbuhan sangat terhambat dengan ukuran pelepah dan panjang batang daun jauh lebih pendek. Produksi Tandan Buah Segar menurun 50-80% dari normal, tandan berukuran sangat kecil dengan buah sedikit, berat tandan rata-rata hanya 5-8 kg dibanding normal 15-20 kg. Kualitas buah menurun dengan rendemen minyak lebih rendah. Sistem perakaran kurang berkembang dengan volume akar samping sangat terbatas. Analisis jaringan daun menunjukkan kandungan Nitrogen kurang dari 2.0% (normal 2.5-2.8%), Magnesium kurang dari 0.15% (normal 0.25-0.35%), sering kekurangan Seng, Boron, dan Besi. Garis kuning bersifat menetap dan sulit diperbaiki bahkan dengan pemupukan perbaikan intensif.', 'Perbaikan status nutrisi tanaman melalui pemupukan perbaikan intensif dan berkelanjutan. Aplikasi Urea 3-5 kg per pohon per tahun (2-3 kali lipat dosis normal) dalam 3-4 kali pemberian terpisah. Untuk area endemik, dosis pemeliharaan ditingkatkan 20-30% dari rekomendasi standar. Pemupukan Magnesium melalui Kieserit atau Dolomit 1-2 kg per pohon 2-3 kali per tahun. Aplikasi lewat daun dengan Magnesium sulfat 1-2% (10-20 gram per liter) setiap 2-4 minggu selama 3-6 bulan. Pemupukan lengkap dengan unsur mikro Seng, Boron, Tembaga, Mangan, Besi dalam bentuk terikat untuk ketersediaan lebih baik.\r\n\r\nPerbaikan sifat kimia tanah dengan aplikasi kapur pertanian atau Dolomit 1-3 ton per hektar untuk menaikkan pH tanah masam dan meningkatkan ketersediaan Kalsium dan Magnesium. Aplikasi bahan organik seperti kompos, limbah cair pabrik kelapa sawit padat, atau tandan kosong sawit 20-40 kg per pohon per tahun untuk meningkatkan kapasitas tukar kation tanah dan daya simpan air. Perbaikan drainase atau irigasi tergantung kondisi lahan untuk memastikan tanaman tidak mengalami tekanan air. Pada tanah dengan drainase buruk, buat parit drainase dan bedengan tinggi. Pada lahan kering, penutup tanah untuk konservasi kelembaban. Pengendalian nematoda parasit melalui aplikasi nematisida atau agen pengendali hayati. Penggunaan bibit dengan latar belakang genetik lebih toleran. Pembuangan tanaman dengan gejala sangat berat, lakukan penanaman ulang dengan bibit unggul. Pemantauan respons terhadap perlakuan setiap 3-6 bulan melalui penilaian visual dan analisis daun.', '9b569901c67aaf52588e0d2a46adefb6.jpeg'),
(4, 'Anthracnose', 'Penyakit antraknosa pada kelapa sawit disebabkan oleh jamur Colletotrichum gloeosporioides yang merupakan patogen dengan jangkauan luas dapat menyerang berbagai tanaman tropika. Jamur ini bersifat setengah biotrofik yang pada fase awal hidup pada jaringan hidup kemudian berubah menjadi nekrotrofik. Jamur menghasilkan konidia atau spora tak kawin dalam jumlah sangat besar yang disebarkan melalui percikan air hujan, angin, serangga, dan alat pertanian terkontaminasi.\r\n\r\nKonidia yang jatuh pada permukaan tanaman berkecambah membentuk struktur penetrasi yang dapat menembus lapisan lilin daun atau buah secara langsung tanpa memerlukan luka. Setelah penetrasi, jamur berkembang dalam jaringan tengah daun menghasilkan enzim seperti selulase, pektinase, dan poligalakturonase yang merusak dinding sel tanaman menyebabkan kematian jaringan. Infeksi dapat terjadi pada semua organ tanaman tetapi paling sering pada daun muda, tandan bunga, dan buah muda.\r\n\r\nFaktor pendukung perkembangan penyakit meliputi kelembaban nisbi sangat tinggi lebih dari 85% untuk jangka waktu lama, curah hujan tinggi dan sering, suhu optimal 25-30 derajat Celsius, luka pada jaringan tanaman akibat hujan es, angin kencang, atau serangga, pemupukan Nitrogen berlebihan yang menyebabkan jaringan tanaman berair dan rentan, kepadatan tajuk tinggi menciptakan iklim mikro lembab. Patogen dapat bertahan pada sisa tanaman terinfeksi, gulma inang alternatif, atau sebagai infeksi laten. Pada kondisi menguntungkan, populasi patogen meningkat cepat menyebabkan wabah.', 'Gejala antraknosa bervariasi tergantung organ yang terserang. Pada daun, gejala awal berupa bercak kecil diameter 2-5 mm, berbentuk bulat hingga lonjong, berwarna coklat muda dengan tepi lebih gelap. Bercak dapat muncul di mana saja pada helaian daun. Seiring waktu, bercak membesar dan menyatu membentuk bercak mati tidak beraturan yang luas. Pada tahap lanjut, bagian tengah bercak menjadi abu-abu terang dengan pinggiran coklat tua menciptakan penampilan seperti sasaran tembak. Dalam kondisi lembab, terlihat massa konidia berwarna merah muda atau jingga pada permukaan lesi. Daun terserang parah mengalami kematian jaringan luas, mengering, dan gugur sebelum waktunya menyebabkan rontoknya daun yang menurunkan fotosintesis hingga 30-40%.\r\n\r\nPada tandan bunga atau perbungaan, antraknosa menyebabkan bunga gugur atau gagal berkembang, dengan gejala berupa pencoklatan dan pengerutan bunga individual terutama bunga betina. Pada buah atau brondolan, gejala dimulai dengan bercak kecil berwarna coklat pada permukaan buah yang cepat membesar membentuk lesi cekung diameter 1-2 cm. Buah terinfeksi tidak berkembang sempurna, mengkerut, dan mudah lepas dari tandan menyebabkan masalah buah rontok. Infeksi pada buah sangat menurunkan kualitas Tandan Buah Segar karena buah busuk meningkatkan kadar Asam Lemak Bebas. Pada serangan berat, hingga 30-50% buah dalam satu tandan dapat terinfeksi. Serangan pada tandan muda (1-3 bulan setelah penyerbukan) lebih merusak dibanding tandan tua. Kondisi basah dan lembab dapat memicu wabah antraknosa yang tiba-tiba dan parah.', 'Pengendalian antraknosa memerlukan kombinasi strategi praktek budidaya dan pengendalian kimia. Aplikasi fungisida pelindung dan penyembuh adalah komponen utama terutama saat cuaca menguntungkan untuk penyakit. Fungisida berbahan aktif tembaga seperti tembaga oksiklorida atau tembaga hidroksida 3-4 gram per liter air efektif sebagai pelindung, aplikasi setiap 2-3 minggu selama periode kritis. Fungisida kontak lain seperti mankozeb atau klorotalonil 2-3 gram per liter dapat digunakan bergantian untuk mencegah resistensi.\r\n\r\nUntuk tindakan penyembuhan pada tanaman dengan gejala, fungisida sistemik berbahan aktif triazol seperti propikonazol, tebukonazol, atau difenokonazol 0.5-1 ml per liter sangat efektif. Fungisida sistemik dapat diserap dan bergerak dalam jaringan tanaman. Aplikasi dengan penyemprotan merata ke seluruh tajuk terutama bagian bawah daun. Volume semprot untuk tanaman dewasa 3-5 liter per pohon. Pergiliran bahan aktif fungisida dari kelompok kimia berbeda sangat penting untuk mencegah resistensi. Waktu aplikasi sangat kritis, aplikasi pencegahan sebelum puncak musim hujan lebih efektif.\r\n\r\nSanitasi kebun sangat penting untuk mengurangi sumber penular, buang dan musnahkan daun tua atau sakit terinfeksi, jangan menumpuk di piringan. Tandan terserang berat sebaiknya dipanen dan dibuang. Pemangkasan pelepah tua dan tidak produktif sesuai prosedur standar untuk meningkatkan sirkulasi udara. Hindari pemangkasan berlebihan yang membuat tanaman stres. Pengendalian gulma di sekitar piringan dan gawangan. Pengaturan populasi tanaman tidak terlalu padat untuk sirkulasi udara baik. Perbaikan drainase untuk mengurangi air tergenang dan kelembaban. Pemupukan berimbang hindari aplikasi berlebihan nitrogen. Pastikan Kalium memadai untuk memperkuat dinding sel. Pengendalian hayati menggunakan Trichoderma atau Bacillus subtilis dapat diintegrasikan. Pemantauan berkala terutama selama periode berisiko tinggi untuk deteksi dini.', 'cd3a8cdac7aadfe341b58b5e4c190a61.jpg'),
(5, 'Penyakit Tajuk', 'Penyakit tajuk disebabkan oleh kompleks jamur patogen yang meliputi Fusarium oxysporum bentuk khusus elaeidis, Thielaviopsis paradoxa, dan kadang Marasmius palmivorus. Fusarium oxysporum adalah patogen dalam tanah yang dapat bertahan dalam tanah dalam bentuk klamidospora hingga bertahun-tahun. Infeksi dimulai dari sistem perakaran dimana jamur menembus melalui luka pada akar, kemudian berkembang dalam sistem pembuluh xilem tanaman. Jamur menghasilkan racun jamur dan enzim yang menyumbat pembuluh xilem mengganggu perpindahan air dan nutrisi.\r\n\r\nThielaviopsis paradoxa adalah patogen luka yang menginfeksi melalui luka pada pangkal pelepah atau batang, menyebabkan pembusukan jaringan dalam dan akhirnya mempengaruhi area tajuk. Patogen ini menghasilkan artrokonidia dan aleuriokonidia yang dapat menyebar melalui air, angin, dan perpindahan mekanis.\r\n\r\nPenyakit tajuk lebih sering terjadi pada tanaman yang mengalami tekanan akibat kekeringan berkepanjangan yang melemahkan sistem pertahanan tanaman, genangan air atau genangan yang menyebabkan akar stres dan mudah terserang, ketidakseimbangan nutrisi terutama kekurangan Boron, Kalsium, atau Kalium, kerusakan mekanis pada area tajuk akibat pemangkasan tidak tepat, serangan hama seperti kumbang tanduk yang membuat luka pada pucuk, dan sanitasi buruk dimana sisa tanaman terinfeksi dibiarkan di lapangan. Penyakit dapat menyerang tanaman di semua umur tetapi lebih sering pada tanaman produktif. Dalam beberapa kasus, infeksi bersifat laten dimana patogen sudah ada dalam jaringan tetapi belum menyebabkan gejala sampai tanaman mengalami pemicu stres.', 'Gejala penyakit tajuk sangat khas dan mudah dikenali pada tahap sedang hingga parah. Gejala utama adalah kegagalan daun tua untuk mati dan lepas secara normal, sehingga terjadi penumpukan pelepah tua yang tetap menggantung di tajuk tanaman menciptakan penampilan mahkota kusut atau kusam. Normalnya, pelepah tua akan mengering, mati, dan patah atau dipangkas, tetapi pada tanaman dengan penyakit tajuk, pelepah tua tetap menempel meskipun sudah kering total.\r\n\r\nDaun-daun baru yang muncul tampak tidak normal, lebih pendek dari normal, dengan batang daun yang kaku dan rapuh atau kaku dan mudah patah. Anak daun sering tidak membuka sempurna, tetap tergulung atau terpuntir, dan warna hijau lebih pucat. Pertumbuhan vegetatif menjadi sangat terhambat dengan laju produksi daun yang menurun drastis, misalnya dari normal 20-24 pelepah per tahun menjadi hanya 10-15 pelepah. Produksi buah menurun signifikan hingga 40-60% dari normal karena perbandingan jenis kelamin berubah dengan dominasi bunga jantan, dan bunga betina yang terbentuk sering gugur. Tandan yang terbentuk berukuran kecil dengan jumlah buah sedikit.\r\n\r\nPada serangan berat, dapat terjadi keruntuhan seluruh tajuk dimana seluruh pucuk tanaman mati, namun batang dan sistem akar mungkin masih hidup sehingga tanaman dapat menghasilkan tunas samping atau tunas pangkal. Namun tunas samping ini jarang produktif dan pertumbuhannya tidak normal. Jika area tajuk dibedah, terlihat perubahan warna jaringan dalam dengan warna coklat hingga hitam, tekstur lunak dan berpori, kadang ada rongga berisi cairan. Bau busuk mungkin ada tetapi tidak sekuat busuk kuncup. Sistem pembuluh pada pelepah menunjukkan pencoklatan atau penghitaman. Analisis sistem akar menunjukkan adanya busuk akar dengan akar berwarna coklat atau hitam dan mudah putus.', 'Pengendalian penyakit tajuk menantang karena patogen berada dalam jaringan dalam yang sulit dijangkau fungisida. Strategi harus menyeluruh mencakup pencegahan, pengelolaan budidaya, dan perlakuan. Pemangkasan atau pemangkasan pelepah harus dilakukan dengan teknik dan waktu yang tepat untuk meminimalkan pelukaan. Gunakan peralatan pemangkasan yang tajam dan steril, disinfeksi dengan alkohol 70% atau natrium hipoklorit 2% setelah setiap tanaman. Jangan memangkas terlalu dekat dengan batang, sisakan tunggul pelepah sekitar 2-3 cm. Pangkas hanya pelepah yang sudah tidak produktif. Waktu pemangkasan sebaiknya saat cuaca kering untuk luka cepat mengering.\r\n\r\nSanitasi kebun adalah krusial, buang dan bakar semua pelepah pangkas dan sisa tanaman yang terinfeksi, jangan menumpuk di piringan. Tanaman dengan gejala parah dan produktivitas menurun sebaiknya diberantas dan diganti dengan bibit sehat. Untuk tanaman dengan gejala awal hingga sedang, perlakuan dengan fungisida sistemik dapat dicoba. Suntik atau siram fungisida berbahan aktif karbendazim, benomil, atau triazol seperti propikonazol ke area tajuk atau siram tanah di zona akar dengan dosis tinggi 5-10 ml produk komersial per tanaman. Ulangi aplikasi setiap 1-2 bulan selama 4-6 bulan. Aplikasi jamur hayati seperti Trichoderma harzianum atau Pseudomonas fluorescens dapat melengkapi fungisida kimia.\r\n\r\nPerbaikan nutrisi tanaman sangat penting untuk meningkatkan ketahanan alami. Pastikan pasokan memadai Kalium (2.5-3 kg KCl per pohon per tahun) untuk kekuatan dinding sel, Boron (30-50 gram Boraks per pohon per tahun) untuk pembelahan sel dan penguatan jaringan, dan Kalsium untuk keutuhan membran. Aplikasi lewat daun dengan campuran unsur mikro setiap 3-4 minggu. Optimalisasi pengelolaan air, hindari genangan dan kekeringan. Pastikan drainase memadai, berikan irigasi tambahan saat musim kering. Pengendalian hama terutama kumbang tanduk yang membuat luka pada pucuk harus intensif. Gunakan perangkap feromon, pengendalian hayati dengan jamur Metarhizium, dan sanitasi tempat berkembang biak. Program pemantauan berkala untuk mendeteksi gejala dini.', 'bc7687da0df164a4763d662a06b2707f.jpg'),
(6, 'Akar Busuk', 'Penyakit akar busuk disebabkan oleh jamur Armillaria mellea yang merupakan patogen dalam tanah menyerang akar dan pangkal batang tanaman sawit. Jamur ini adalah parasit fakultatif yang dapat hidup sebagai saprofit pada bahan organik mati atau sebagai parasit pada tanaman hidup. Armillaria mellea menghasilkan rizomorf yang merupakan struktur seperti akar berwarna coklat kehitaman yang dapat tumbuh melalui tanah mencari inang baru. Rizomorf dapat bertahan dalam tanah untuk periode yang lama dan berfungsi sebagai organ penyebaran dan infeksi.\r\n\r\nInfeksi dimulai ketika rizomorf atau pertumbuhan miselium melakukan kontak dengan akar tanaman, kemudian penetrasi terjadi melalui luka atau langsung menembus jaringan akar yang sehat. Setelah penetrasi, miselium berkembang di bawah kulit batang atau akar membentuk lapisan miselium berwarna putih yang khas. Jamur menghasilkan enzim yang merusak jaringan kayu menyebabkan busuk putih. Perusakan jaringan akar mengganggu penyerapan air dan nutrisi menyebabkan tanaman stres dan layu meskipun kondisi tanah lembab.\r\n\r\nFaktor yang meningkatkan risiko infeksi meliputi lahan yang sebelumnya ditumbuhi hutan dengan tunggul dan sisa akar yang terinfeksi Armillaria, drainase buruk yang menyebabkan akar stres, pemadatan tanah yang menghambat perkembangan akar sehat, dan pelukaan pada akar akibat aktivitas mekanis. Penyakit lebih sering terjadi pada tanaman muda (Tanaman Belum Menghasilkan) dan dapat menyebabkan kematian tinggi jika tidak dikendalikan. Penyebaran terjadi melalui kontak akar dimana rizomorf tumbuh dari tanaman terinfeksi ke tanaman sehat yang berdekatan.', 'Gejala akar busuk dimulai dengan daun yang menunjukkan tanda-tanda layu meskipun kondisi tanah cukup lembab. Daun menjadi kuning atau klorosis dimulai dari daun tua kemudian menyebar ke daun muda. Pertumbuhan tanaman terhambat dengan produksi daun yang menurun dan ukuran pelepah yang lebih kecil dari normal. Tanaman terlihat tidak sehat dengan kekuatan yang menurun.\r\n\r\nGejala khas pada akar dan pangkal batang adalah keberadaan lapisan miselium putih atau pertumbuhan miselium berbentuk kipas di bawah kulit batang atau pada permukaan akar yang terinfeksi. Jika kulit batang atau akar dikupas, terlihat lapisan miselium tebal berwarna putih seperti kipas yang sangat khas untuk Armillaria. Rizomorf berwarna coklat kehitaman seperti akar dapat ditemukan pada permukaan akar atau dalam tanah di sekitar tanaman terinfeksi. Akar membusuk dengan warna coklat hingga hitam, tekstur lunak, dan mudah putus saat ditarik. Sistem perakaran mengalami kerusakan luas dengan kehilangan sebagian besar akar samping dan akar serabut.\r\n\r\nPada tahap lanjut, tanaman menjadi sangat lemah dan mudah rebah atau tumbang karena jangkar akar yang buruk. Dalam kondisi angin kencang atau tanah lembab, tanaman terinfeksi parah dapat roboh dengan mudah. Tanaman yang terinfeksi berat biasanya akan mati dalam beberapa bulan hingga 1-2 tahun setelah gejala jelas terlihat. Pada malam hari atau kondisi lembab, kadang terlihat pendar cahaya atau cahaya fosfor dari pertumbuhan miselium atau rizomorf yang merupakan fenomena unik pada beberapa spesies Armillaria. Gejala harus dibedakan dari busuk akar yang disebabkan patogen lain atau tekanan tak hidup seperti genangan air.', 'Pengendalian akar busuk memerlukan pendekatan terpadu yang dimulai dari persiapan lahan. Untuk lahan baru yang berasal dari konversi hutan, pembuangan tunggul dan sisa akar sangat penting untuk menghilangkan sumber penular Armillaria. Tunggul harus dibongkar total atau diperlakukan dengan fungisida atau herbisida untuk membunuh miselium sebelum penanaman. Lahan dibiarkan istirahat beberapa bulan dengan tanaman penutup untuk mengurangi tekanan penular.\r\n\r\nUntuk tanaman yang sudah terinfeksi, pemberantasan adalah tindakan terbaik. Cabut dan musnahkan tanaman sakit beserta seluruh sistem perakaran. Pastikan semua akar dan rizomorf terangkat dari tanah. Sisa tanaman dibakar atau dikubur jauh dari area perkebunan. Lubang bekas tanaman sakit diperlakukan dengan fungisida atau agen pengendali hayati sebelum penanaman ulang. Perbaiki drainase agar tanah tidak terlalu lembab dengan membuat saluran drainase yang memadai. Hindari genangan air yang menyebabkan akar stres dan lebih mudah terserang.\r\n\r\nAplikasi agen pengendali hayati seperti Trichoderma harzianum atau Gliocladium virens pada lubang tanam dengan dosis 50-100 gram dapat menekan Armillaria melalui persaingan dan parasitisme miselium. Beberapa penelitian menunjukkan Trichoderma efektif mengurangi tingkat infeksi. Perlakuan kimia dengan fungisida berbahan aktif fosetyl-Al dapat diaplikasikan sebagai siraman tanah di zona perakaran dengan dosis 5-10 gram per liter, volume 5-10 liter per tanaman. Aplikasi diulang setiap 2-3 bulan untuk tanaman di area berisiko tinggi.\r\n\r\nParit isolasi dapat dilakukan dengan membuat parit sedalam 60-80 cm di sekeliling tanaman terinfeksi atau kelompok untuk secara fisik menghalangi penyebaran rizomorf ke tanaman sehat. Penghalang fisik seperti lembaran plastik dapat dipasang dalam parit. Perbaikan praktek agronomi dengan pemupukan berimbang untuk mempertahankan kekuatan tanaman, hindari nitrogen berlebihan yang mendorong pertumbuhan jaringan berair. Pastikan kalium dan kalsium memadai. Minimalkan pelukaan pada akar saat kegiatan pemeliharaan. Pemantauan berkala untuk deteksi dini dan tindakan segera terhadap infeksi baru.', '30be5293db4a672ba1fdd087a2a90b78.webp'),
(7, 'Bercak Daun', 'Penyakit bercak daun Curvularia disebabkan oleh jamur Curvularia spp. atau Helminthosporium spp. yang menyerang daun tanaman sawit. Jamur ini termasuk dalam kelompok hyphomycetes yang menghasilkan konidia sebagai spora aseksual untuk reproduksi dan penyebaran. Curvularia spp. adalah patogen fakultatif yang dapat hidup sebagai saprofit pada bahan organik mati atau sebagai parasit lemah pada tanaman yang stres.\r\n\r\nInfeksi terjadi ketika konidia yang disebarkan oleh angin atau percikan air hujan jatuh pada permukaan daun. Dalam kondisi lembab dengan adanya air bebas pada permukaan daun, konidia berkecambah membentuk tabung kecambah yang penetrasi melalui stomata atau langsung menembus kutikula dan epidermis. Setelah penetrasi, hifa berkembang dalam jaringan mesofil menyebabkan kematian sel dan nekrosis jaringan. Jamur menghasilkan enzim dan toksin yang merusak sel tanaman.\r\n\r\nFaktor yang mendukung perkembangan penyakit meliputi kelembaban tinggi dengan periode basah berkepanjangan pada permukaan daun minimal 8-12 jam, suhu optimal 25-30°C, sirkulasi udara yang buruk di dalam kanopi yang meningkatkan kelembaban iklim mikro, defisiensi nutrisi terutama Nitrogen dan Kalium yang melemahkan tanaman, dan stres abiotik seperti kekeringan atau genangan air. Tanaman yang sudah stres lebih rentan terhadap infeksi. Penyakit lebih sering terjadi pada musim hujan atau periode dengan kelembaban tinggi. Patogen dapat bertahan pada sisa daun terinfeksi atau sebagai saprofit pada material organik dalam tanah.', 'Gejala awal berupa bercak kecil berwarna coklat muda pada helaian daun dengan bentuk bulat atau oval, diameter awal 2-5 mm. Bercak memiliki tepi yang jelas berbatas tegas dengan jaringan sehat. Seiring perkembangan penyakit, bercak membesar hingga diameter 1-2 cm dan kadang lebih besar. Bercak matang menunjukkan zonasi konsentris dengan bagian tengah berwarna abu-abu atau tan dan bagian tepi berwarna coklat gelap atau coklat kemerahan, menciptakan penampilan seperti sasaran atau pola mata banteng.\r\n\r\nBercak dapat muncul di mana saja pada helaian daun tetapi lebih sering pada bagian ujung dan tepi daun. Pada infeksi berat, beberapa lesi berkembang pada satu helaian daun dan bercak-bercak dapat menyatu membentuk area nekrotik yang luas dan tidak beraturan. Jaringan daun di dalam bercak menjadi kering dan rapuh, kadang bagian tengah bercak dapat pecah dan gugur membentuk gejala lubang tembak. Daun yang terserang parah mengalami nekrosis luas, menguning, mengering, dan gugur sebelum waktunya menyebabkan kerontokan daun.\r\n\r\nKerontokan daun yang parah dapat menurunkan luas daun aktif untuk fotosintesis hingga 30-40%, yang berdampak pada pertumbuhan tanaman dan produksi TBS. Dalam kondisi lembab tinggi, dapat terlihat sporulasi pada permukaan lesi dengan penampilan gelap atau kehitaman dari massa konidia. Gejala harus dibedakan dari bercak daun yang disebabkan patogen lain seperti Pestalotiopsis atau Cercospora yang memiliki karakteristik lesi berbeda. Diagnosis konfirmasi memerlukan isolasi dan identifikasi jamur dengan konidia melengkung khas yang memiliki beberapa septa.', 'Pengendalian bercak daun Curvularia memerlukan kombinasi praktik budidaya dan pengendalian kimia. Aplikasi fungisida adalah metode utama untuk mengendalikan penyakit ini. Fungisida protektif berbahan aktif mankozeb atau propineb dengan dosis 2-3 gram per liter air dapat diaplikasikan sebagai perlakuan pencegahan sebelum periode kritis. Fungisida kontak ini membentuk lapisan pelindung pada permukaan daun yang mencegah perkecambahan dan penetrasi spora. Aplikasi dilakukan setiap 2-3 minggu selama musim hujan atau periode tekanan penyakit tinggi.\r\n\r\nUntuk perlakuan kuratif pada tanaman yang sudah menunjukkan gejala, fungisida sistemik berbahan aktif triazol seperti propikonazol, tebukonazol, atau azoksistrobin dapat digunakan dengan dosis 0,5-1 ml per liter air. Fungisida sistemik dapat diserap daun dan bergerak dalam jaringan memberikan perlindungan dari dalam. Aplikasi dengan penyemprotan menyeluruh pada seluruh kanopi terutama bagian bawah daun. Volume semprot 3-5 liter per pohon untuk tanaman dewasa. Rotasi bahan aktif fungisida diperlukan untuk mencegah perkembangan resistensi.\r\n\r\nManajemen budidaya sangat penting untuk mengurangi tekanan penyakit. Sanitasi kebun dengan mengumpulkan dan memusnahkan daun terinfeksi yang gugur untuk mengurangi sumber inokulum. Jangan biarkan sisa daun menumpuk di piringan atau gawangan. Pemangkasan untuk meningkatkan sirkulasi udara dan penetrasi cahaya dalam kanopi dapat mengurangi kelembaban dan menciptakan lingkungan yang kurang menguntungkan bagi patogen. Namun hindari pemangkasan berlebihan yang dapat menyebabkan tanaman stres. Pengaturan jarak tanam yang memadai untuk pergerakan udara yang baik.\r\n\r\nPemupukan seimbang untuk menjaga vigor tanaman dan ketahanan. Pastikan Nitrogen yang cukup untuk pertumbuhan daun yang sehat dan Kalium yang cukup untuk memperkuat dinding sel dan meningkatkan ketahanan penyakit. Hindari nitrogen berlebihan yang mendorong pertumbuhan vegetatif yang rimbun dan lebih rentan. Aplikasi pupuk berbasis silikon dapat meningkatkan kekuatan mekanis jaringan. Manajemen air dengan memperbaiki drainase untuk mencegah genangan air, hindari irigasi di atas yang membasahi daun. Pengendalian biologis dengan Trichoderma atau Bacillus spp. dapat diintegrasikan sebagai semprot daun. Pemantauan rutin terutama selama periode berisiko tinggi untuk deteksi dini dan intervensi tepat waktu.', '6cf71a72a90a23144432296d9305f35d.jpeg'),
(8, 'Layu Fusarium', 'Penyakit layu Fusarium disebabkan oleh jamur Fusarium oxysporum yang menyerang sistem pembuluh akar dan batang tanaman kelapa sawit. Jamur ini adalah patogen tular tanah yang dapat bertahan dalam tanah dalam bentuk klamidospora yang tahan terhadap kondisi buruk untuk periode yang sangat lama, bahkan hingga 10-20 tahun tanpa inang. F. oxysporum adalah patogen yang memiliki banyak forma spesialis yang spesifik inang, meskipun pada sawit forma spesialis yang spesifik belum sepenuhnya dikarakterisasi.\r\n\r\nInfeksi dimulai dari akar dimana jamur penetrasi melalui luka pada ujung akar atau melalui zona pemanjangan dimana epidermis masih belum sepenuhnya berkembang. Setelah penetrasi, miselium tumbuh ke dalam korteks akar dan kemudian invasi ke dalam pembuluh xilem. Dalam xilem, miselium berkembang dan menyebar secara akropetal (ke atas) menuju batang dan daun. Jamur menghasilkan mikrokonidia yang dapat bergerak dalam cairan xilem mencapai bagian tanaman yang lebih tinggi. Kolonisasi pembuluh xilem menyebabkan penyumbatan yang mengganggu transportasi air dari akar ke tajuk.\r\n\r\nJamur juga memproduksi mikotoksin dan enzim yang merusak sel parenkim xilem dan menyebabkan pembentukan tilosis, yaitu tonjolan dari sel parenkim ke dalam pembuluh xilem sebagai respons pertahanan tanaman, yang ironisnya malah memperburuk penyumbatan. Kombinasi pertumbuhan miselium, tilosis, dan getah yang dihasilkan tanaman menyebabkan disfungsi pembuluh yang parah. Faktor yang meningkatkan kerentanan meliputi stres abiotik seperti kekeringan atau genangan air, ketidakseimbangan nutrisi, infestasi nematoda yang melukai akar, dan kesehatan tanah yang buruk. Penyakit dapat menyebar melalui alat yang terkontaminasi, bahan tanam terinfeksi, atau air yang terinfeksi.', 'Gejala khas penyakit layu Fusarium adalah layu pada daun yang terjadi secara tiba-tiba meskipun kondisi air dalam tanah memadai. Layu biasanya dimulai pada satu sisi tanaman atau layu sektoral, kemudian menyebar ke sisi lainnya. Daun-daun menunjukkan kehilangan turgor, menjadi lemas dan terkulai. Warna daun berubah dari hijau normal menjadi kuning atau klorosis, dimulai dari daun tua kemudian ke daun muda. Dalam beberapa kasus, daun dapat menunjukkan klorosis sepihak dimana hanya setengah daun yang menguning sementara separuh lainnya masih hijau.\r\n\r\nPertumbuhan tanaman terhambat sangat parah dengan produksi daun yang menurun drastis dan ukuran pelepah yang mengecil. Tanaman terlihat kerdil dan tidak vigor. Akar menunjukkan tanda-tanda kerusakan dengan busuk akar berwarna coklat hingga hitam. Sistem akar berkembang buruk dengan sedikit akar lateral dan tidak adanya ujung akar putih yang sehat. Jika batang atau pelepah dipotong secara melintang, terlihat perubahan warna pembuluh berupa pencoklatan atau penghitaman jaringan xilem yang merupakan gejala diagnostik penting. Perubahan warna dapat terlihat sebagai garis-garis berwarna coklat yang mengikuti berkas pembuluh.\r\n\r\nPada stadium lanjut, seluruh tajuk mengering dan tanaman dapat mati dalam beberapa bulan setelah gejala layu muncul. Kecepatan perkembangan tergantang pada virulensi strain patogen, kondisi lingkungan, dan kerentanan inang. Tanaman muda atau bibit persemaian lebih rentan dan dapat mati lebih cepat dibanding sawit dewasa. Gejala harus dibedakan dari layu yang disebabkan oleh stres kekeringan, kerusakan akar oleh hama, atau penyakit pembuluh lainnya. Diagnosis konfirmasi memerlukan isolasi jamur dari jaringan pembuluh dan identifikasi berdasarkan karakteristik morfologi seperti mikrokonidia, makrokonidia, dan pembentukan klamidospora.', 'Pengendalian layu Fusarium menantang karena sifat infeksi pembuluh yang sulit dijangkau dengan fungisida. Pencegahan adalah strategi terpenting. Gunakan bahan tanam yang sehat dan bersertifikat bebas dari patogen. Bibit harus dari persemaian terpercaya dengan praktik sanitasi yang baik. Hindari penanaman di area dengan riwayat layu Fusarium. Jika harus menanam di area yang mencurigakan, lakukan perlakuan tanah terlebih dahulu.\r\n\r\nSolarisasi tanah dengan menutup tanah dengan plastik bening selama 4-6 minggu di musim kemarau dapat mengurangi inokulum dalam tanah melalui efek panas. Suhu tanah dapat mencapai 45-50°C yang mematikan bagi banyak patogen. Aplikasi agen pengendalian hayati seperti Trichoderma harzianum, T. asperellum, atau strain Fusarium non-patogenik pada lubang tanam dengan dosis 50-100 gram dapat memberikan perlindungan melalui kompetisi dan induksi ketahanan. Bio-fungisida harus diaplikasikan berulang setiap 3-6 bulan untuk mempertahankan populasi pelindung.\r\n\r\nPerlakuan kimia dengan fungisida sistemik seperti benomil, karbendazim, atau fungisida triazol dapat dicoba untuk tanaman terinfeksi yang terdeteksi dini. Fungisida diaplikasikan sebagai kocoran tanah di zona akar dengan dosis 5-10 gram per liter, volume 10-20 liter per tanaman. Perlakuan diulang setiap 1-2 bulan. Efektivitasnya bervariasi dan seringkali terbatas karena kesulitan dalam mencapai konsentrasi memadai dalam xilem. Untuk tanaman yang terinfeksi parah, eradikasi adalah pilihan terbaik untuk mencegah penyebaran. Buang dan musnahkan seluruh tanaman termasuk sistem akar.\r\n\r\nPraktik budidaya sangat penting. Rotasi dengan tanaman bukan inang jika memungkinkan dapat mengurangi inokulum dalam tanah seiring waktu. Perbaikan kesehatan tanah dengan bahan organik seperti kompos untuk mendorong populasi mikroba menguntungkan yang antagonis terhadap patogen. Pemupukan seimbang untuk menjaga vigor tanaman. Pastikan Kalium dan unsur mikro yang memadai. Manajemen air dengan menghindari stres kekeringan dan genangan air. Drainase yang baik sangat penting. Sanitasi alat dan peralatan dengan mendisinfeksi menggunakan natrium hipoklorit atau alkohol setelah bekerja pada tanaman terinfeksi. Pemantauan rutin untuk deteksi dini sehingga intervensi dapat dilakukan sebelum penyakit menyebar luas.', '7f922fe4bc795283eb97408296d2435a.jpeg'),
(9, 'Penyakit Upas', 'Penyakit upas disebabkan oleh jamur Corticium salmonicolor yang merupakan basidiomycetes menyerang batang dan cabang tanaman. Jamur ini adalah parasit luka yang memerlukan luka atau cedera pada kulit batang atau cabang untuk infeksi awal. C. salmonicolor menghasilkan basidiospora yang disebarkan oleh angin atau percikan air hujan ke berbagai bagian tanaman atau ke tanaman lain di sekitarnya.\r\n\r\nInfeksi dimulai ketika spora mendarat pada luka atau retakan pada kulit batang, kemudian berkecambah dan hifa penetrasi ke dalam jaringan korteks. Miselium berkembang di bawah kulit batang membentuk anyaman miselium yang akhirnya menembus ke permukaan membentuk tubuh buah atau basidiokarp. Jamur menghasilkan enzim yang mendegradasi jaringan kulit dan kambium, menyebabkan efek pengikatan yang mengganggu translokasi nutrisi dan hasil fotosintesis antara akar dan tajuk.\r\n\r\nFaktor yang mendukung perkembangan penyakit meliputi kelembaban tinggi yang mendukung sporulasi dan infeksi, sirkulasi udara yang buruk di dalam kanopi, keberadaan luka pada batang akibat pemangkasan, kerusakan serangga, atau cedera mekanis, dan tanaman yang stres atau vigor rendah lebih rentan. Penyakit lebih sering terjadi pada area dengan curah hujan tinggi dan pada tanaman yang tumbuh di kondisi teduh atau cahaya buruk yang meningkatkan kelembaban. Penyebaran terjadi melalui spora udara, percikan hujan, dan mungkin juga melalui alat pemangkasan yang terkontaminasi.', 'Gejala khas penyakit upas adalah munculnya pertumbuhan miselium pada permukaan kulit batang atau cabang yang terinfeksi. Awalnya, tampak benang miselium putih atau untaian seperti sutra pada kulit batang di sekitar area luka atau cedera. Seiring perkembangan, miselium membentuk anyaman yang lebih tebal dan berubah warna menjadi merah muda salmon atau oranye merah muda yang sangat khas dan distingtif untuk penyakit ini, sehingga disebut penyakit merah muda dalam literatur Inggris.\r\n\r\nKerak miselium menutupi area yang cukup luas pada keliling batang atau cabang, bisa mencapai puluhan sentimeter panjangnya. Di bawah kerak miselium, kulit batang mengalami degradasi dan terpisah dari kayu di bawahnya, menciptakan rongga. Kulit menjadi lunak, kenyal, dan dapat dengan mudah dikupas. Basidiokarp atau tubuh buah mungkin berkembang pada permukaan miselium dengan penampilan seperti kerak atau bercak.\r\n\r\nBagian tanaman di atas area yang terinfeksi menunjukkan gejala kemunduran karena gangguan fungsi pembuluh. Daun menguning, mengering, dan cabang atau bahkan seluruh pelepah dapat mati jika pengikatan sempurna. Pada infeksi parah yang melingkar sempurna pada batang (pengikatan sempurna), seluruh tanaman dapat mati. Tanaman yang terinfeksi menunjukkan vigor berkurang, pertumbuhan buruk, dan produktivitas menurun. Cabang atau pelepah yang terinfeksi menjadi rapuh dan mudah patah pada area yang diserang, terutama saat angin atau saat penanganan. Gejala lebih parah pada tanaman muda atau bibit persemaian dibanding sawit dewasa.', 'Pengendalian penyakit upas memerlukan kombinasi sanitasi, praktik budidaya, dan perlakuan kimia. Sanitasi adalah tindakan paling penting. Cabang, pelepah, atau bagian batang yang terinfeksi harus dipangkas dan dibuang segera setelah deteksi. Pangkas pada area yang sehat beberapa sentimeter di bawah lesi yang terlihat untuk memastikan pembuangan jaringan terinfeksi secara sempurna. Material pangkasan harus dibakar atau dimusnahkan, tidak boleh dibiarkan di lapangan karena dapat menjadi sumber inokulum.\r\n\r\nAlat pemangkasan harus didisinfeksi setelah setiap pemotongan dengan mencelupkan dalam larutan natrium hipoklorit 2% atau alkohol 70% untuk mencegah penularan patogen ke tanaman lain. Luka bekas pangkasan dapat diperlakukan dengan pasta fungisida atau penutup luka untuk melindungi dari infeksi ulang. Pasta fungisida berbahan tembaga atau campuran bordeaux dapat diaplikasikan pada permukaan luka.\r\n\r\nPengendalian kimia dengan aplikasi fungisida dapat dilakukan terutama pada area dengan tekanan penyakit tinggi. Fungisida berbahan aktif tembaga seperti tembaga oksiklorida atau tembaga hidroksida dengan dosis 3-4 gram per liter dapat disemprotkan ke batang dan cabang yang rentan, terutama setelah pemangkasan atau saat ada luka. Aplikasi fungisida sistemik seperti triazol (propikonazol, tebukonazol) dengan dosis 1-2 ml per liter juga efektif, dapat diaplikasikan sebagai semprot batang atau cat pada area terinfeksi. Aplikasi ulang setiap 3-4 minggu selama periode berisiko tinggi.\r\n\r\nManajemen budidaya dengan meningkatkan sirkulasi udara di dalam dan sekitar kanopi melalui jarak tanam yang tepat dan pemangkasan selektif untuk mengurangi kelembaban. Hindari naungan berlebihan dan kepadatan. Kurangi kelembaban iklim mikro untuk menciptakan kondisi yang kurang menguntungkan bagi pertumbuhan jamur. Pemupukan seimbang untuk menjaga vigor tanaman dan meningkatkan ketahanan alami. Pastikan Kalium, Kalsium, dan unsur mikro yang memadai. Hindari Nitrogen berlebihan yang mendorong pertumbuhan vegetatif yang subur dan lebih rentan.\r\n\r\nManajemen luka sangat penting. Minimalkan luka yang tidak perlu pada batang dan cabang. Saat pemangkasan diperlukan, lakukan pada cuaca kering untuk memungkinkan pengeringan dan penyembuhan luka yang cepat. Aplikasikan fungisida pelindung atau sealant pada luka segar. Pengendalian hama serangga yang dapat menciptakan luka pada kulit batang. Pemantauan rutin untuk deteksi dini infeksi sehingga tindakan segera dapat diambil sebelum penyakit menyebar luas.', '822a2bccacf4c861bc06720330a90f0a.jpg');
INSERT INTO `jenis_penyakit` (`id_penyakit`, `nama_penyakit`, `penyebab`, `gejala`, `cara_pengendalian`, `gambar_ilustrasi`) VALUES
(10, 'Penyakit Bintik Hitam', 'Penyakit bintik hitam disebabkan oleh jamur Pestalotiopsis spp. yang menyerang daun tanaman kelapa sawit terutama pada kondisi lembab tinggi. Jamur ini termasuk dalam kelompok coelomycetes yang menghasilkan konidia dalam struktur aservuli. Pestalotiopsis adalah patogen oportunistik yang umumnya menyerang tanaman yang sudah stres atau jaringan yang sudah lemah, meskipun pada kondisi menguntungkan dapat juga menginfeksi jaringan sehat.\r\n\r\nInfeksi terjadi ketika konidia yang disebarkan oleh percikan air hujan atau angin mendarat pada permukaan daun. Dalam kondisi lembab dengan adanya air bebas, konidia berkecambah dan apresorium terbentuk untuk penetrasi. Penetrasi dapat terjadi langsung melalui kutikula atau melalui stomata dan luka. Setelah penetrasi, hifa berkembang dalam jaringan mesofil menyebabkan kematian sel dan nekrosis jaringan. Jamur menghasilkan enzim dan metabolit beracun yang merusak sel inang.\r\n\r\nFaktor yang mendukung perkembangan penyakit meliputi kelembaban sangat tinggi dengan durasi basah daun berkepanjangan minimal 10-12 jam, curah hujan sering dan deras, sirkulasi udara buruk, ketidakseimbangan nutrisi terutama defisiensi Kalium yang melemahkan ketahanan, stres abiotik seperti kekeringan atau genangan air yang membuat tanaman rentan, dan keberadaan luka atau cedera pada daun akibat hujan es, angin, serangga, atau kerusakan mekanis. Penyakit lebih umum pada musim hujan atau di area dengan kelembaban tinggi sepanjang tahun. Patogen dapat bertahan pada sisa tanaman mati sebagai saprofit.', 'Gejala utama adalah munculnya bintik-bintik hitam kecil pada permukaan daun, baik di permukaan atas maupun permukaan bawah. Bintik berbentuk bulat atau oval, ukuran sangat kecil sekitar 1-3 mm diameter. Warna bintik hitam pekat atau coklat gelap hingga hitam, dengan atau tanpa halo kuning di sekitarnya. Bintik dapat muncul tersebar di seluruh permukaan helaian daun.\r\n\r\nPada infeksi ringan hingga sedang, bintik-bintik tetap kecil dan terpisah, tidak menyatu. Namun pada infeksi berat, jumlah bintik sangat banyak bisa mencapai ratusan hingga ribuan bintik per anak daun, memberikan penampilan berbintik-bintik yang khas. Penyatuan bintik dapat terjadi membentuk area nekrotik yang lebih luas. Jaringan daun di sekitar bintik dapat menguning atau klorosis.\r\n\r\nDaun yang terserang parah mengalami penguningan dini, nekrosis luas, dan kerontokan daun. Kapasitas fotosintesis menurun karena berkurangnya area daun hijau. Pada kondisi lembab tinggi, dapat terlihat aservuli atau tubuh buah pada pusat bercak dengan penampilan titik-titik gelap kecil yang merupakan struktur penghasil spora. Cairan hitam atau rembesan gelap dapat keluar dari aservuli dalam kondisi sangat lembab.\r\n\r\nMeskipun bintik individual kecil, pada infeksi berat dengan banyaknya jumlah lesi, efek kumulatif dapat secara signifikan mengurangi fotosintesis dan melemahkan tanaman. Tingkat kerontokan daun meningkat dan rentang hidup daun memendek. Laju pertumbuhan tanaman menurun dan pada sawit muda atau bibit persemaian, infeksi parah dapat menyebabkan kemunduran signifikan. Gejala harus dibedakan dari bintik hitam yang disebabkan jamur jelaga (pertumbuhan jamur hitam pada embun madu dari kutu daun atau sisik) atau penyakit bercak tar lainnya.', 'Pengendalian penyakit bintik hitam memerlukan pendekatan terpadu yang menggabungkan praktik budidaya dan pengendalian kimia. Aplikasi fungisida adalah metode pengendalian utama. Fungisida protektif berbahan aktif tembaga seperti tembaga oksiklorida, tembaga hidroksida, atau campuran bordeaux dengan dosis 3-4 gram per liter efektif sebagai semprot pencegahan. Fungisida berbahan tembaga membentuk lapisan pelindung pada permukaan daun yang mencegah perkecambahan spora dan penetrasi. Aplikasi setiap 2-3 minggu selama periode berisiko tinggi seperti musim hujan.\r\n\r\nFungisida sistemik atau penetran seperti mankozeb, klorotalonil, atau triazol (propikonazol, difenokonazol) dengan dosis sesuai rekomendasi juga dapat digunakan, terutama untuk perlakuan kuratif. Fungisida sistemik diserap ke dalam jaringan dan memberikan perlindungan internal. Rotasi bahan aktif fungisida dari kelompok kimia berbeda penting untuk menunda perkembangan resistensi. Cakupan semprot menyeluruh sangat penting, pastikan permukaan daun atas dan bawah terlindungi.\r\n\r\nManajemen budidaya fokus pada mengurangi kelembaban dan durasi basah daun. Pemangkasan untuk meningkatkan sirkulasi udara dan penetrasi cahaya dapat mengurangi kelembaban di bagian dalam kanopi. Buang pelepah bawah yang menyentuh tanah atau yang sudah tidak produktif untuk meningkatkan pergerakan udara. Manajemen jarak tanam dengan menghindari kerapatan berlebih. Pada persemaian, pastikan jarak yang memadai antara bibit dan ventilasi yang baik.\r\n\r\nPerbaikan drainase untuk mencegah genangan air dan mengurangi kelembaban tanah yang berkontribusi pada kelembaban atmosfer tinggi. Hindari irigasi di atas jika memungkinkan, gunakan irigasi tetes atau irigasi permukaan tanah untuk menjaga dedaunan tetap kering. Jika irigasi di atas tidak dapat dihindari, lakukan pada pagi hari sehingga dedaunan dapat cepat kering. Manajemen air dengan irigasi bijaksana, hindari kelebihan air.\r\n\r\nManajemen nutrisi dengan pemupukan seimbang untuk menjaga vigor tanaman. Kalium yang memadai (2-3 kg KCl per pohon per tahun untuk sawit dewasa) sangat penting untuk ketahanan penyakit. Kalium memperkuat dinding sel dan meningkatkan regulasi osmotik. Hindari Nitrogen berlebihan yang mendorong dedaunan subur dan lebih rentan. Pastikan unsur mikro yang cukup terutama Seng, Tembaga, dan Mangan yang terlibat dalam mekanisme pertahanan.\r\n\r\nSanitasi dengan mengumpulkan dan memusnahkan daun yang terinfeksi parah yang gugur untuk mengurangi beban inokulum. Hindari meninggalkan sisa di piringan atau gawangan. Pengendalian biologis menggunakan mikroorganisme antagonis seperti Trichoderma spp., Bacillus subtilis, atau Pseudomonas fluorescens dapat diintegrasikan sebagai semprot daun atau sebagai bagian dari program manajemen tanah. Pemantauan rutin untuk menilai tingkat keparahan penyakit dan efektivitas tindakan pengendalian, sesuaikan program sesuai kebutuhan.', '09b082c505ee1ea9c157815dca7f8c83.jpeg'),
(11, 'Penyakit Karat Daun', 'Penyakit karat daun disebabkan oleh jamur Puccinia spp. yang merupakan parasit obligat hanya dapat hidup pada jaringan tanaman hidup. Jamur karat adalah basidiomycetes dengan siklus hidup yang kompleks sering melibatkan inang alternatif. Pada kelapa sawit, spesies yang umum terlibat belum sepenuhnya dikarakterisasi, tetapi gejala dan tanda konsisten dengan jamur karat.\r\n\r\nInfeksi dimulai ketika urediospora atau teliospora yang disebarkan angin mendarat pada permukaan daun. Dalam kondisi lembab dengan adanya embun atau air hujan, spora berkecambah dan tabung kecambah penetrasi melalui stomata pada permukaan bawah daun. Jamur tidak dapat menembus kutikula utuh, sehingga masuk ketat melalui bukaan alami. Setelah penetrasi, hifa interselular berkembang di dalam jaringan mesofil dan haustorium terbentuk yang menembus ke dalam sel inang untuk menyerap nutrisi.\r\n\r\nInfeksi menyebabkan gangguan fungsi seluler normal dan akhirnya kematian sel. Pustula atau uredinia berkembang di bawah epidermis, dan ketika matang akan menerobos melalui epidermis melepaskan massa urediospora berwarna oranye atau karat. Urediospora adalah spora berulang yang dapat menyebabkan beberapa siklus infeksi dalam satu musim tanam. Faktor yang menguntungkan meliputi suhu sedang 18-25°C, kelembaban tinggi >80%, embun sering atau hujan ringan, dan sirkulasi udara buruk. Penyakit lebih umum pada ketinggian yang lebih tinggi dengan suhu lebih dingin dan kelembaban tinggi yang persisten.', 'Gejala khas adalah munculnya pustula atau bercak menonjol berwarna oranye, kuning-oranye, atau karat pada permukaan bawah daun. Pustula berbentuk bulat atau oval, ukuran 1-3 mm diameter, sedikit menonjol atau cembung. Pada infeksi berat, pustula sangat banyak menutupi bagian signifikan dari permukaan bawah daun. Permukaan atas daun di atas pustula menunjukkan bercak kuning atau area klorosis sebagai hasil infeksi di bawahnya.\r\n\r\nKetika pustula matang, epidermis pecah dan massa urediospora berwarna oranye terpapar. Urediospora mudah rontok, dan saat disentuh dapat meninggalkan bubuk oranye pada jari. Sporulasi berat pada kondisi kelembaban tinggi. Seiring perkembangan, jaringan terinfeksi di sekitar pustula dapat menjadi nekrotik, berubah coklat dan kering. Daun yang terinfeksi berat menjadi klorosis, lemah, dan rapuh. Penuaan daun dini dan kerontokan dapat terjadi pada infeksi parah.\r\n\r\nKapasitas fotosintesis sangat berkurang karena kerusakan jaringan yang mengandung klorofil dan gangguan fungsi daun normal. Laju transpirasi dapat meningkat secara abnormal melalui pustula yang pecah, menyebabkan stres air. Laju pertumbuhan tanaman menurun, vigor berkurang, dan pada infeksi parah yang berkelanjutan, hasil dapat terpengaruh. Daun muda atau pelepah yang belum matang lebih rentan dibanding daun yang sudah matang sepenuhnya. Gejala lebih menonjol pada area teduh atau pada pelepah bawah dimana kelembaban lebih tinggi.', 'Pengendalian karat daun memerlukan kombinasi praktik budidaya dan aplikasi fungisida. Perlakuan fungisida adalah metode pengendalian paling efektif. Fungisida sistemik berbahan aktif triazol seperti propikonazol, tebukonazol, atau triadimefon sangat efektif melawan jamur karat dengan dosis 0,5-1 ml per liter. Triazol menghambat biosintesis ergosterol yang penting untuk integritas membran jamur. Fungisida strobilurin (azoksistrobin, piraklostrobin) juga sangat efektif dengan mode aksi yang berbeda, dapat digunakan dalam program rotasi.\r\n\r\nWaktu aplikasi sangat kritis. Semprot pencegahan sebelum pustula berkembang lebih efektif dibanding perlakuan kuratif setelah sporulasi berat. Pantau kondisi cuaca dan aplikasikan fungisida sebelum periode kelembaban tinggi atau periode embun berkepanjangan yang diprediksi. Interval semprot biasanya 3-4 minggu, dapat diperpendek menjadi 2 minggu selama periode tekanan penyakit tinggi. Cakupan menyeluruh pada permukaan bawah daun penting karena ini adalah lokasi infeksi utama.\r\n\r\nManajemen budidaya fokus pada mengurangi kelembaban dan basah daun. Pemangkasan untuk meningkatkan sirkulasi udara dan penetrasi cahaya ke kanopi bawah. Peningkatan paparan cahaya dan pergerakan udara mengurangi kelembaban dan persistensi embun. Manajemen jarak tanam dengan menghindari kerapatan berlebih, pertahankan kepadatan tanam yang direkomendasikan. Pada persemaian, pastikan jarak dan ventilasi yang memadai.\r\n\r\nPengendalian gulma di sekitar sawit untuk meningkatkan sirkulasi udara di permukaan tanah. Penutupan gulma yang padat menjebak kelembaban dan menghambat pergerakan udara. Manajemen air dengan menghindari irigasi di atas atau aplikasikan air pada pagi hari untuk memungkinkan pengeringan cepat. Kurangi basah daun yang tidak perlu. Perbaikan drainase untuk mengurangi kontribusi kelembaban tanah terhadap kelembaban atmosfer.\r\n\r\nManajemen nutrisi dengan pemupukan seimbang. Kalium dan Silikon yang memadai dapat meningkatkan ketahanan tanaman. Deposisi Silikon di dinding sel meningkatkan kekuatan mekanis dan ketahanan terhadap penetrasi. Beberapa penelitian menunjukkan pemupukan Silikon mengurangi keparahan karat. Hindari Nitrogen berlebihan yang mendorong jaringan subur lebih rentan.\r\n\r\nSanitasi dengan membuang dan memusnahkan pelepah yang terinfeksi parah dapat membantu mengurangi tingkat inokulum, meskipun penyebaran spora melalui udara membuat sanitasi lengkap sulit. Untuk area bernilai tinggi atau persemaian, penyaringan pelindung atau modifikasi naungan dapat mengurangi infiltrasi spora dan menciptakan iklim mikro yang kurang menguntungkan. Pemantauan rutin untuk deteksi dini dan intervensi tepat waktu sebelum penyakit mencapai tingkat epidemi.', '5f1c3ca4f0c1fc679c9bcf399efdd208.jpeg'),
(12, 'Penyakit Akar Putih', 'Penyakit akar putih disebabkan oleh jamur Rigidoporus microporus (sinonim: Rigidoporus lignosus) yang merupakan jamur pelapuk putih menyerang sistem perakaran tanaman. Jamur ini adalah basidiomycetes yang bersifat patogen nekrotrofik dengan kisaran inang yang luas meliputi berbagai spesies pohon termasuk karet, kelapa sawit, dan tanaman tahunan berkayu lainnya. R. microporus dapat bertahan dalam tanah pada tunggul dan sisa akar untuk periode yang lama sebagai saprofit.\r\n\r\nInfeksi terjadi melalui kontak akar dimana hifa atau rizomorf dari tunggul atau akar terinfeksi tumbuh melalui tanah dan bertemu akar sawit yang sehat. Penetrasi dapat terjadi langsung melalui epidermis atau melalui luka dan retakan. Jamur menghasilkan pertumbuhan miselium putih yang secara ekstensif mengkolonisasi permukaan akar dan kulit, muncul sebagai anyaman putih tebal atau pertumbuhan seperti lembaran. Rizomorf yang merupakan agregasi hifa seperti untaian dapat tumbuh jarak yang cukup jauh melalui tanah mencari inang baru.\r\n\r\nJamur menghasilkan enzim ligninolitik dan selulolitik yang mendegradasi komponen kayu menyebabkan pelapukan putih. Akar yang terinfeksi kehilangan integritas struktural, menjadi lunak dan kenyal, dan akhirnya hancur. Gangguan sistem akar sangat mengganggu penyerapan air dan nutrisi. Faktor yang meningkatkan risiko meliputi keberadaan tunggul terinfeksi atau sisa akar dalam tanah dari tanaman sebelumnya, drainase buruk menyebabkan genangan air dan stres akar, tanah yang padat, dan luka pada akar dari kerusakan mekanis atau serangan hama. Penyakit lebih umum di area penanaman ulang dengan sanitasi yang tidak memadai terhadap sisa tanaman sebelumnya.', 'Gejala awal pada bagian udara adalah penurunan bertahap dengan penguningan daun tua secara progresif bergerak ke daun muda. Layu dapat terjadi terutama selama periode kering atau cuaca panas meskipun kelembaban tanah memadai. Tanaman menunjukkan pertumbuhan kerdil, vigor berkurang, dan produksi daun buruk. Ukuran pelepah lebih kecil dan warna lebih pucat dibanding sawit sehat.\r\n\r\nGejala karakteristik adalah keberadaan anyaman miselium putih pada akar yang terinfeksi. Ketika akar terinfeksi terpapar atau digali, terlihat pertumbuhan seperti kain tebal putih menutupi permukaan akar dan kulit yang menempel. Miselium dapat meluas dari permukaan akar ke tanah sekitarnya. Rizomorf yang muncul sebagai untaian seperti akar berwarna putih atau krem dapat ditemukan menempel pada akar atau berjalan melalui tanah. Rizomorf bervariasi dalam diameter dari seperti benang (1-2 mm) hingga setebal pensil (5-10 mm).\r\n\r\nAkar yang terinfeksi menunjukkan pembusukan progresif dengan kulit menjadi lunak dan mudah terlepas dari inti kayu. Korteks akar hancur hanya menyisakan inti pembuluh yang akhirnya juga rusak. Akar berubah coklat gelap hingga kehitaman dan menjadi rapuh. Pembusukan sistem akar yang luas menyebabkan penahan yang buruk, dan sawit dapat mudah roboh terutama pada kondisi tanah basah atau saat angin kencang.\r\n\r\nPada stadium lanjut, dedaunan sangat klorosis, pelepah mengering, dan tanaman menurun dengan cepat. Tanaman dapat mati dalam 6-12 bulan setelah munculnya gejala tergantung pada tingkat kerusakan sistem akar dan kondisi lingkungan. Sawit muda lebih rentan dan menunjukkan penurunan lebih cepat dibanding sawit dewasa dengan cadangan akar yang lebih besar. Tubuh buah (basidiokarp) jarang terlihat pada kelapa sawit, berbeda dari pohon karet dimana basidiokarp berbentuk kurung umumnya berkembang pada pangkal batang.', 'Pengendalian akar putih memerlukan pendekatan komprehensif dimulai dari persiapan lahan. Untuk area penanaman ulang dengan riwayat R. microporus, pembuangan menyeluruh tunggul dan sisa akar dari tanaman sebelumnya sangat penting. Tunggul harus digali sepenuhnya atau diracun dengan arborisida untuk membunuh jamur sebelum membusuk sempurna. Biarkan periode bera 6-12 bulan dengan tanaman penutup untuk mengurangi tingkat inokulum.\r\n\r\nUntuk sawit terinfeksi yang terdeteksi dini, parit isolasi dapat dicoba. Parit dengan kedalaman 80-100 cm dan lebar 30-40 cm digali mengelilingi sawit terinfeksi pada radius 2-3 meter untuk secara fisik mengisolasi dan memutus akar terinfeksi. Parit dapat dilapisi dengan lembaran plastik dan ditimbun kembali. Akar terinfeksi dalam zona isolasi harus dibuang dan dimusnahkan. Metode ini padat karya tetapi dapat menyelamatkan sawit dengan infeksi terbatas.\r\n\r\nSawit yang terinfeksi parah harus dieradikasi sepenuhnya. Gali seluruh sistem akar sebaik mungkin. Akar terinfeksi dan tunggul harus dibuang dari lapangan dan dimusnahkan dengan dibakar atau dikubur dalam jauh dari area penanaman. Lubang tanam dari sawit yang dieradikasi diperlakukan dengan fungisida atau agen pengendalian hayati sebelum penanaman ulang.\r\n\r\nPerlakuan kimia dengan fungisida memiliki efektivitas terbatas karena kesulitan dalam mengirimkan konsentrasi memadai ke sistem akar yang luas. Kocoran tanah dengan fungisida sistemik seperti tridemorph atau senyawa fosfonat dapat dicoba untuk sawit dengan infeksi dini. Aplikasi memerlukan volume besar (20-50 liter per sawit) dengan perlakuan berulang setiap 2-3 bulan. Efektivitas biaya dipertanyakan untuk aplikasi skala lapangan.\r\n\r\nPengendalian biologis menggunakan Trichoderma spp. atau Gliocladium spp. lebih menjanjikan dan berkelanjutan. Inokulan konsentrasi tinggi diaplikasikan pada lubang tanam dan di sekitar sawit yang sudah ada dapat membantu menekan R. microporus melalui kompetisi, mikoparasitisme, dan antibiosis. Aplikasi harus diulang 3-4 kali per tahun untuk mempertahankan populasi pelindung.\r\n\r\nPraktik budidaya dengan meningkatkan drainase sangat penting. Kondisi tergenang air menyebabkan stres akar dan menguntungkan patogen. Bangun sistem drainase yang memadai dan pertahankan fungsinya. Hindari pemadatan dari lalu lintas mesin berat. Pemupukan seimbang untuk menjaga vigor. Kalium, Kalsium, dan unsur mikro yang memadai mendukung kesehatan akar. Pemantauan rutin untuk deteksi dini, menandai sawit terinfeksi untuk pelacakan dan mencegah penyebaran melalui alat yang terkontaminasi.', '00799ea59a9ae30fc2254b7bd2efa608.jpeg'),
(13, 'Busuk Tandan', 'Penyakit busuk tandan disebabkan oleh jamur Marasmius palmivorus yang menyerang tandan buah kelapa sawit terutama pada cuaca lembab. Jamur ini adalah basidiomycetes yang termasuk dalam famili Marasmiaceae dengan karakteristik menghasilkan basidiospora untuk reproduksi. M. palmivorus adalah patogen yang secara khusus menyerang bunga dan tandan yang sedang berkembang, meskipun dapat juga ditemukan sebagai saprofit pada material tanaman mati.\r\n\r\nInfeksi terjadi ketika basidiospora yang disebarkan oleh angin atau percikan air hujan mendarat pada bunga betina atau buah muda yang sedang berkembang. Dalam kondisi lembab dengan basah berkepanjangan, spora berkecambah dan hifa penetrasi ke dalam jaringan. Infeksi dapat dimulai pada tahap antesis (pembungaan) atau pada tandan muda beberapa minggu setelah penyerbukan. Jamur berkembang dalam jaringan menyebabkan kematian sel dan busuk buah.\r\n\r\nFaktor yang sangat mendukung perkembangan penyakit adalah kelembaban sangat tinggi >90% dengan basah persisten pada permukaan tandan selama minimal 12-24 jam, curah hujan deras dan sering terutama saat pembungaan dan tahap perkembangan buah awal, sirkulasi udara buruk di dalam kanopi yang menjebak kelembaban, dan dedaunan lebat yang mencegah pengeringan cepat tandan setelah hujan. Penyakit sangat musiman, dengan kejadian puncak selama musim basah berkepanjangan. Arsitektur tandan yang kompak dengan buah yang rapat memberikan lingkungan mikro yang menguntungkan bagi pertumbuhan jamur. Defisiensi Kalium dapat membuat buah rentan terhadap infeksi dengan melemahkan jaringan buah.', 'Gejala awal pada buah adalah munculnya bercak kecil jenuh air atau lesi berwarna coklat pada permukaan buah individual. Lesi awalnya melingkar dengan diameter 5-10 mm, kemudian cepat membesar dan menyatu mempengaruhi beberapa buah yang berdekatan. Area terinfeksi berubah coklat gelap hingga hitam dengan tekstur lunak berair. Pelunakan jaringan terjadi dan buah terinfeksi mudah lepas dari tandan.\r\n\r\nPada kondisi kelembaban tinggi, pertumbuhan miselium putih dapat terlihat pada permukaan buah terinfeksi dan di antara buah, tampak seperti benang kapas atau seperti jaring menghubungkan buah. Miselium dapat secara ekstensif menutupi bagian tandan. Tubuh buah berupa struktur kecil seperti jamur atau basidiokarp dengan diameter tudung 5-15 mm kadang berkembang pada pertumbuhan miselium, meskipun tidak selalu ada.\r\n\r\nBau tidak sedap atau bau busuk keluar dari tandan terinfeksi karena kerusakan jaringan dan invasi bakteri sekunder. Bau sangat khas dan menyengat. Buah terinfeksi mengalami pembusukan progresif, menjadi lembek dan hancur. Cairan atau rembesan berwarna gelap dapat keluar dari area terinfeksi. Gugur buah prematur atau absisi sangat tinggi, dengan sejumlah besar buah terinfeksi jatuh ke tanah sebelum matang.\r\n\r\nPada infeksi parah, bagian substansial dari tandan (30-60% atau lebih) dapat terpengaruh, sangat mengurangi hasil yang dapat dipanen. Buah yang tersisa yang tidak terinfeksi langsung mungkin tampak normal tetapi kualitas minyak dapat terganggu dengan tingkat Asam Lemak Bebas (ALB) yang meningkat karena kedekatan dengan jaringan yang membusuk dan potensi infeksi awal. Tandan yang terinfeksi berat sering dipanen prematur sebagai tindakan pengendalian kerusakan, tetapi panen prematur menghasilkan kandungan dan kualitas minyak yang berkurang.\r\n\r\nDampak pada hasil dan kualitas sangat signifikan terutama pada perkebunan dengan kejadian penyakit tinggi. Kerugian ekonomi substansial tidak hanya dari berkurangnya tonase tetapi juga dari penalti harga untuk TBS berkualitas rendah dengan ALB tinggi. Kejadian penyakit dapat bervariasi secara signifikan antar lokasi, perkebunan, dan musim, dengan beberapa area mengalami masalah kronis sementara yang lain relatif bebas.', 'Pengendalian busuk tandan memerlukan pendekatan terpadu dengan waktu yang tepat. Aplikasi fungisida adalah metode pengendalian utama dan harus ditargetkan pada periode infeksi kritis. Fungisida berbahan aktif mankozeb, klorotalonil, atau senyawa tembaga dengan dosis 2-3 gram per liter diaplikasikan pada bunga dan tandan muda yang sedang berkembang. Waktu aplikasi kritis adalah: (1) saat antesis ketika bunga betina reseptif, (2) 4-6 minggu setelah antesis saat buah masih kecil dan rentan, dan (3) aplikasi tambahan setiap 3-4 minggu selama periode basah berkepanjangan.\r\n\r\nCakupan menyeluruh sangat penting karena lokasi infeksi adalah bunga dan buah yang harus dilindungi langsung. Penyemprotan volume tinggi diperlukan untuk memastikan fungisida mencapai bagian dalam tandan. Untuk sawit dewasa, peralatan semprot dengan tekanan dan jangkauan yang cukup diperlukan. Waktu aplikasi sebelum periode hujan yang diprediksi lebih efektif dibanding aplikasi reaktif setelah penyakit sudah terbentuk. Rotasi bahan aktif fungisida untuk mencegah resistensi.\r\n\r\nManajemen budidaya fokus pada mengurangi kelembaban di zona tandan. Pemangkasan untuk meningkatkan sirkulasi udara dan penetrasi cahaya. Buang pertumbuhan vegetatif berlebih yang menjebak kelembaban di sekitar tandan. Pemangkasan pelepah yang tepat (mempertahankan 48-56 pelepah pada sawit dewasa) menyeimbangkan antara kapasitas fotosintesis yang memadai dan sirkulasi udara yang baik. Hindari pemangkasan berlebihan yang menyebabkan stres tanaman atau pemangkasan kurang yang menciptakan kanopi yang terlalu lebat.\r\n\r\nPraktik panen penting. Pertahankan ronde panen yang tepat (interval 10-12 hari untuk sawit dewasa, 7-10 hari untuk sawit muda) untuk memastikan tandan dipanen pada kematangan optimal. Tandan terlalu matang lebih rentan terhadap infeksi dan kerusakan. Tandan terinfeksi harus dipanen segera dan diproses secara terpisah untuk mencegah kontaminasi tandan sehat. Sanitasi titik pengumpulan dengan pembersihan rutin untuk membuang material terinfeksi.\r\n\r\nManajemen nutrisi dengan pemupukan Kalium yang memadai (2,5-3 kg KCl per pohon per tahun untuk sawit dewasa) memperkuat jaringan buah dan meningkatkan ketahanan. Kecukupan Boron juga penting untuk integritas dinding buah. Hindari defisiensi Kalium yang membuat buah lebih rentan. Nutrisi seimbang secara keseluruhan menjaga kesehatan dan vigor tanaman.\r\n\r\nManajemen air pada perkebunan beririgasi, hindari metode irigasi di atas yang membasahi dedaunan dan tandan. Irigasi tetes lebih disukai. Pada area tanpa irigasi, pastikan drainase yang baik untuk mencegah genangan air yang meningkatkan kelembaban atmosfer. Seleksi genetik dengan memilih bahan tanam yang menghasilkan tandan dengan arsitektur kurang kompak dapat memberikan beberapa keuntungan dengan memfasilitasi sirkulasi udara yang lebih baik dalam tandan dan pengeringan lebih cepat. Pemantauan pola cuaca dan kejadian penyakit untuk mengantisipasi periode berisiko tinggi dan mengintensifkan tindakan pengendalian sesuai kebutuhan.', '9f47b3f5d28cf7db607a81d47088291d.jpeg'),
(14, 'Bercak Coklat Daun', 'Penyakit bercak coklat daun disebabkan oleh jamur Helminthosporium spp. yang menyerang daun tanaman kelapa sawit. Jamur ini termasuk dalam hyphomycetes berselaput gelap yang menghasilkan konidia berwarna gelap. Helminthosporium adalah genus yang terdiri dari banyak spesies dengan spesifisitas inang yang bervariasi, dan pada kelapa sawit, beberapa spesies dapat terlibat. Jamur ini adalah parasit fakultatif yang dapat hidup sebagai saprofit pada material organik mati atau sebagai patogen lemah pada tanaman hidup, terutama yang mengalami stres.\r\n\r\nInfeksi terjadi ketika konidia yang disebarkan oleh arus angin atau percikan hujan mendarat pada permukaan daun. Dengan adanya kelembaban, konidia berkecambah dan tabung kecambah penetrasi langsung melalui kutikula atau masuk melalui stomata atau luka. Apresorium dapat terbentuk untuk memfasilitasi penetrasi. Setelah terbentuk dalam jaringan mesofil, hifa interselular tumbuh dan nutrisi diserap dari sel inang melalui haustorium atau penetrasi sel langsung.\r\n\r\nEnzim dan toksin yang diproduksi oleh patogen menyebabkan kematian sel dan nekrosis jaringan, menghasilkan lesi yang khas. Sporulasi terjadi pada permukaan lesi, dengan konidiofor muncul melalui stomata atau pecahan di epidermis, membawa konidia yang dapat memulai infeksi baru. Faktor yang mendukung perkembangan penyakit termasuk kelembaban tinggi dengan basah daun berkepanjangan (>10 jam), suhu sedang 22-28°C, sirkulasi udara buruk, ketidakseimbangan nutrisi terutama defisiensi Nitrogen atau Kalium, stres air atau stres abiotik lainnya, dan adanya luka atau jaringan yang menua. Penyakit lebih umum pada daun tua dan pada tanaman yang tumbuh dalam kondisi suboptimal.', 'Gejala khas adalah bercak atau lesi pada daun yang memanjang atau berbentuk oval, berwarna coklat. Lesi awalnya kecil (3-5 mm) tetapi membesar seiring waktu hingga mencapai panjang 1-2 cm dan lebar 0,5-1 cm. Bercak umumnya lebih panjang daripada lebar, sering sejajar dengan tulang daun atau berorientasi memanjang pada anak daun.\r\n\r\nWarna lesi bervariasi dari tan atau coklat muda pada tahap awal hingga coklat gelap atau coklat kemerahan pada lesi matang. Pusat lesi mungkin menjadi berwarna lebih terang atau keabu-abuan seiring penuaan, dengan tepi coklat gelap menciptakan penampilan zonasi atau cincin konsentris. Tepi lesi biasanya jelas, terpisah nyata dari jaringan hijau sehat.\r\n\r\nBeberapa lesi dapat berkembang pada satu anak daun, dan pada infeksi parah, lesi banyak dan dapat menyatu membentuk area nekrotik yang lebih besar dan tidak beraturan. Penyatuan menghasilkan pencoklatan luas dan pengeringan jaringan daun. Anak daun yang terpengaruh menjadi klorosis, mengering, dan mungkin menunjukkan ujung terbakar atau nekrosis tepi. Penuaan daun prematur dan kerontokan dapat terjadi pada tanaman yang terinfeksi berat.\r\n\r\nPada kondisi kelembaban tinggi, sporulasi jamur terlihat pada permukaan lesi sebagai pertumbuhan bubuk hijau zaitun gelap hingga hitam, mewakili massa konidia dan konidiofor. Sporulasi biasanya lebih berlimpah pada permukaan bawah daun. Daun tua umumnya menunjukkan gejala lebih parah dibanding daun muda, mencerminkan periode paparan yang lebih lama dan kemungkinan ketahanan yang berkurang.\r\n\r\nEfisiensi fotosintesis berkurang karena hilangnya area daun fungsional. Pada infeksi parah yang meluas, vigor tanaman secara keseluruhan menurun, laju pertumbuhan melambat, dan produktivitas terpengaruh. Sawit muda atau bibit persemaian dapat terpengaruh parah dengan penghambatan pertumbuhan yang signifikan. Gejala harus dibedakan dari penyakit bercak daun lainnya berdasarkan morfologi lesi, warna, ukuran, dan karakteristik sporulasi jamur. Konfirmasi laboratorium melalui pemeriksaan mikroskopis morfologi konidia mungkin diperlukan untuk diagnosis definitif.', 'Pengendalian bercak coklat daun memerlukan kombinasi praktik budidaya dan aplikasi fungisida. Perlakuan fungisida efektif untuk mengelola penyakit terutama pada situasi bernilai tinggi seperti persemaian atau perkebunan muda. Fungisida protektif seperti mankozeb atau propineb dengan dosis 2-3 gram per liter diaplikasikan sebagai semprot pencegahan dapat melindungi pertumbuhan baru dari infeksi. Aplikasi setiap 2-3 minggu selama kondisi penyakit yang menguntungkan.\r\n\r\nFungisida sistemik atau penetran seperti triazol (propikonazol, tebukonazol, difenokonazol) dengan dosis 0,5-1 ml per liter memberikan tindakan kuratif pada infeksi dini dan perlindungan sistemik. Fungisida strobilurin juga efektif. Cakupan semprot menyeluruh penting untuk memastikan permukaan daun terlapisi dengan memadai. Pergantian kelas fungisida penting untuk manajemen resistensi.\r\n\r\nManajemen budidaya sangat penting. Sanitasi dengan membuang dan memusnahkan daun yang terinfeksi berat mengurangi sumber inokulum. Pemangkasan untuk meningkatkan sirkulasi udara dan mengurangi kelembaban dalam kanopi. Jarak yang memadai antara tanaman untuk memfasilitasi pergerakan udara. Hindari kepadatan berlebih terutama di persemaian. Pengendalian gulma untuk mengurangi kelembaban di permukaan tanah.\r\n\r\nManajemen air untuk meminimalkan durasi basah daun. Hindari irigasi di atas jika memungkinkan; gunakan irigasi tetes atau irigasi tanah. Jika irigasi di atas diperlukan, aplikasikan selama pagi hari untuk memungkinkan pengeringan daun yang cepat. Hindari irigasi di sore hari yang menghasilkan basah daun berkepanjangan semalam.\r\n\r\nManajemen nutrisi penting untuk menjaga vigor dan ketahanan tanaman. Pemupukan seimbang dengan Nitrogen yang memadai untuk pertumbuhan dedaunan sehat, Kalium yang cukup (biasanya 2-3 kg KCl per pohon per tahun) untuk memperkuat dinding sel dan meningkatkan ketahanan penyakit, dan unsur mikro yang memadai. Perbaiki defisiensi yang teridentifikasi melalui analisis daun. Hindari Nitrogen berlebihan yang mendorong pertumbuhan subur lebih rentan terhadap infeksi.\r\n\r\nManajemen stres dengan memastikan kondisi tumbuh optimal. Pasokan air yang memadai selama periode kering untuk mencegah stres kekeringan. Drainase yang baik untuk mencegah genangan air. Atasi masalah pemadatan tanah. Minimalkan faktor yang menyebabkan stres pada tanaman dan membuat rentan terhadap penyakit. Ketahanan genetik dengan menggunakan bahan tanam dari persilangan atau famili dengan toleransi yang lebih baik terhadap penyakit daun jika tersedia.\r\n\r\nProgram pemantauan dengan pengawasan rutin untuk menilai tingkat penyakit dan melacak efektivitas tindakan pengendalian. Catat kejadian dan keparahan penyakit dari waktu ke waktu. Gunakan keputusan semprot berbasis ambang batas daripada berbasis kalender untuk mengoptimalkan penggunaan fungisida. Pendekatan terpadu yang menggabungkan semua taktik yang tersedia memberikan manajemen penyakit yang paling efektif dan berkelanjutan.', 'a264f738f88ff384fdd3de9da281adf1.jpeg'),
(15, 'Penyakit Garis Daun', 'Penyakit garis daun disebabkan oleh jamur Cercospora spp. yang merupakan hyphomycetes berselaput gelap menyerang daun tanaman kelapa sawit. Cercospora adalah genus besar yang terdiri dari banyak spesies, banyak di antaranya adalah patogen tanaman dengan tingkat spesifisitas inang yang bervariasi. Pada kelapa sawit, spesies Cercospora spesifik yang terlibat dapat bervariasi menurut wilayah geografis, tetapi gejala umumnya konsisten.\r\n\r\nJamur menghasilkan konidia yang termelanisasi atau berpigmen gelap, biasanya berbentuk obklavat atau seperti jarum dengan beberapa septa. Konidia disebarkan terutama oleh percikan hujan dan sekunder oleh angin. Infeksi terjadi ketika konidia mendarat pada permukaan daun dan berkecambah dengan adanya kelembaban bebas. Tabung kecambah dapat penetrasi langsung melalui kutikula atau masuk melalui stomata. Pembentukan apresorium dapat mendahului penetrasi pada beberapa spesies.\r\n\r\nSetelah terbentuk dalam jaringan daun, hifa interselular tumbuh di antara sel mesofil, menyerap nutrisi dan menyebabkan gangguan sel. Gejala khas berkembang sebagai hasil produksi toksin dan nekrosis jaringan. Stroma terbentuk di bawah epidermis, dan konidiofor muncul melalui bukaan stomata atau pecahan epidermis, membawa konidia yang memulai infeksi sekunder. Sifat poliklik penyakit dengan beberapa generasi per musim dapat menyebabkan intensifikasi penyakit progresif.\r\n\r\nKondisi yang menguntungkan termasuk kelembaban relatif tinggi (>80%), curah hujan sering atau embun deras yang menyediakan basah daun berkepanjangan (>12 jam), suhu sedang (22-28°C), sirkulasi udara buruk, dan stres tanaman dari ketidakseimbangan nutrisi atau faktor lain. Penyakit sering lebih parah pada daun tua dan selama musim basah yang diperpanjang. Tanaman yang tumbuh pada tanah marjinal atau dalam kondisi suboptimal umumnya lebih rentan.', 'Gejala khas adalah pembentukan garis atau goresan pada daun yang memanjang dan sempit, berwarna coklat hingga coklat kemerahan. Lesi dominan linear atau seperti goresan, berjalan sejajar dengan tulang daun, mencerminkan pola pertumbuhan jamur sepanjang jaringan pembuluh. Lebar goresan biasanya 1-3 mm tetapi dapat memanjang beberapa sentimeter.\r\n\r\nGoresan individual awalnya muncul sebagai area berubah warna kecil yang memanjang seiring waktu. Perkembangan warna dari coklat muda atau tan pada tahap awal hingga coklat kemerahan gelap atau coklat cokelat pada lesi matang. Tepi lesi mungkin tidak beraturan atau bergelombang, tetapi orientasi linear keseluruhan dipertahankan. Pada beberapa kasus, lesi dapat mengembangkan halo klorosis ringan di jaringan yang berdekatan.\r\n\r\nBeberapa goresan dapat berkembang pada satu anak daun, terutama pada daun tua. Pada infeksi parah, banyak goresan hadir dan goresan yang berdekatan dapat menyatu, menyebabkan nekrosis luas pada jaringan anak daun. Penyatuan menghasilkan bercak nekrotik tidak beraturan yang lebih besar dengan hilangnya warna hijau normal. Anak daun yang terpengaruh menjadi klorosis secara keseluruhan, akhirnya mengering dan berubah coklat.\r\n\r\nPenuaan prematur dan kerontokan dapat terjadi pada daun yang terinfeksi berat. Sporulasi jamur terlihat pada permukaan lesi sebagai pertumbuhan hijau zaitun gelap hingga keabu-abuan, terutama jelas selama kondisi lembab. Sporulasi terjadi pada permukaan daun atas dan bawah tetapi sering lebih berlimpah di bawah. Pemeriksaan dengan kaca pembesar atau mikroskop menunjukkan konidiofor dan konidia Cercospora yang khas.\r\n\r\nDampak pada kesehatan tanaman tergantung pada keparahan dan luasan infeksi. Infeksi ringan pada beberapa daun tua mungkin memiliki dampak minimal. Infeksi sedang hingga parah yang mempengaruhi area daun substansial mengurangi kapasitas fotosintesis, melemahkan tanaman dan berpotensi mempengaruhi pertumbuhan dan hasil. Sawit muda sangat rentan dengan infeksi parah menyebabkan kemunduran pertumbuhan yang signifikan. Kejadian penyakit sering berfluktuasi musiman, mencapai puncak selama periode basah yang diperpanjang.', 'Pengendalian garis daun Cercospora memerlukan pendekatan manajemen penyakit terpadu. Aplikasi fungisida adalah alat pengendalian utama terutama pada situasi dimana penyakit menyebabkan kerontokan daun signifikan atau mempengaruhi sawit muda. Fungisida protektif seperti klorotalonil, mankozeb, atau produk berbahan tembaga dengan dosis 2-3 gram per liter efektif untuk mencegah infeksi baru saat diaplikasikan secara preventif. Interval aplikasi biasanya 2-3 minggu selama periode tekanan penyakit tinggi.\r\n\r\nFungisida sistemik dari kelompok triazol (propikonazol, difenokonazol, tebukonazol) atau kelompok strobilurin memberikan aktivitas protektif dan kuratif. Dosis biasanya 0,5-1 ml per liter untuk triazol. Fungisida ini dapat menghentikan perkembangan penyakit pada infeksi yang ada dan melindungi pertumbuhan baru. Rotasi kimia fungisida penting untuk menunda perkembangan resistensi. Ajuvan atau perekat-penyebar dapat meningkatkan cakupan dan ketahanan hujan.\r\n\r\nTeknik aplikasi penting untuk memastikan cakupan yang memadai. Volume semprot yang cukup untuk membasahi permukaan daun secara menyeluruh termasuk permukaan bawah dimana sporulasi terjadi. Peralatan dengan tekanan yang cukup dan nozel yang sesuai untuk mencapai atomisasi dan cakupan yang baik. Waktu aplikasi untuk bertepatan dengan pola cuaca - mengaplikasikan sebelum periode basah yang diperpanjang lebih efektif dibanding aplikasi reaktif.\r\n\r\nPraktik budidaya fokus pada memodifikasi lingkungan agar kurang menguntungkan bagi penyakit. Pemangkasan untuk meningkatkan sirkulasi udara dan penetrasi cahaya mengurangi kelembaban dalam kanopi. Pertahankan jumlah pelepah yang tepat (48-56 pada sawit dewasa) seimbang antara kapasitas fotosintesis dan sirkulasi udara. Hindari pemangkasan kurang yang menciptakan kanopi lebat dengan pergerakan udara buruk. Sanitasi dengan membuang daun yang terinfeksi parah dapat mengurangi inokulum, meskipun kelayakan praktis terbatas pada sawit dewasa.\r\n\r\nManajemen jarak dengan mempertahankan kepadatan tanam yang tepat penting untuk pergerakan udara. Perkebunan yang terlalu padat memiliki sirkulasi udara yang lebih buruk dan kelembaban lebih tinggi yang mendukung penyakit. Pengendalian gulma terutama gulma tinggi yang menghalangi pergerakan udara di permukaan tanah. Manajemen air dengan menghindari irigasi di atas atau mengatur waktu irigasi untuk pagi hari meminimalkan durasi basah daun. Pastikan drainase yang baik untuk mencegah genangan air.\r\n\r\nManajemen nutrisi dengan pemupukan seimbang mempertahankan vigor dan ketahanan tanaman. Kalium yang memadai penting untuk kekuatan dinding sel dan ketahanan penyakit secara keseluruhan. Dosis tipikal 2-3 kg KCl per pohon per tahun untuk sawit dewasa, disesuaikan berdasarkan analisis tanah dan daun. Pastikan kecukupan semua unsur makro dan mikro. Perbaiki defisiensi yang teridentifikasi dengan segera.\r\n\r\nPemeliharaan vigor tanaman melalui praktik manajemen optimal. Minimalkan faktor stres. Air yang memadai selama periode kering, drainase yang baik selama periode basah. Atasi keterbatasan tanah. Seleksi genetik dengan menggunakan persilangan atau famili dengan toleransi lebih baik terhadap penyakit daun jika informasi tersebut tersedia dari pemulia. Program pemantauan untuk melacak tingkat penyakit dan mengevaluasi efektivitas pengendalian. Sesuaikan strategi berdasarkan hasil.', '97f229615ec2298d5f11f025f3105e9a.png'),
(16, 'Penyakit Busuk Akar Merah', 'Penyakit busuk akar merah disebabkan oleh jamur Pythium spp. yang merupakan oomycetes atau jamur air menyerang sistem perakaran tanaman sawit. Pythium adalah genus yang terdiri dari banyak spesies, sebagian besar bersifat patogen tular tanah dan tular air. Pythium spp. memiliki siklus hidup yang melibatkan produksi zoospora yang motil dan dapat berenang dalam air tanah menuju ujung akar.\r\n\r\nPythium berkembang dalam kondisi tanah tergenang atau jenuh dimana kadar oksigen rendah dan air bebas melimpah. Zoospora tertarik secara kemotaksis menuju eksudat akar, kemudian membentuk kista pada permukaan akar dan berkecambah untuk menembus jaringan akar. Infeksi biasanya terjadi pada ujung akar muda yang sukulen atau pada area dimana akar rusak. Hifa tumbuh cepat dalam korteks akar, menghasilkan enzim yang mendegradasi dinding sel dan menyebabkan pelunakan jaringan.\r\n\r\nAkar yang terinfeksi kehilangan fungsinya untuk penyerapan air dan nutrisi, menyebabkan gejala stres di atas tanah. Faktor yang sangat mempengaruhi tanaman termasuk drainase buruk dengan genangan air, tanah liat berat dengan aerasi buruk, irigasi berlebihan atau curah hujan berkepanjangan, tanah padat dengan difusi oksigen terbatas, kerusakan akar dari nematoda atau serangga, dan tahap bibit dimana sistem akar belum berkembang dengan baik. Penyakit lebih parah pada kondisi persemaian atau perkebunan muda dibanding sawit dewasa yang sudah mapan dengan sistem akar yang luas. Pythium dapat menyebar melalui air yang terkontaminasi, pergerakan tanah, atau bahan tanaman terinfeksi.', 'Gejala pada sistem perakaran adalah perubahan warna akar dari normal putih atau krem menjadi merah muda, merah, atau coklat kemerahan, yang merupakan gejala khas yang memberikan nama pada penyakit ini. Perubahan warna dimulai pada ujung akar dan berlanjut menuju mahkota. Akar yang terinfeksi tampak jenuh air pada awalnya, kemudian menjadi nekrotik dan berubah coklat gelap hingga hitam pada tahap lanjut. Korteks akar melunak dan mudah terkelupas saat ditangani, hanya menyisakan stele pusat atau inti pembuluh.\r\n\r\nSistem akar rusak secara ekstensif dengan hilangnya akar pengumpan dan rambut akar yang penting untuk penyerapan nutrisi dan air. Akar yang sakit gagal memanjang secara normal dan percabangan sangat berkurang. Pada infeksi parah, sebagian besar sistem akar hancur. Gejala di atas tanah mencerminkan fungsi akar yang terganggu. Bibit atau sawit muda menunjukkan pertumbuhan kerdil dengan produksi daun berkurang dan ukuran pelepah lebih kecil. Daun mungkin tampak klorosis atau menguning, terutama daun tua terlebih dahulu.\r\n\r\nLayu dapat terjadi meskipun kelembaban tanah memadai karena kapasitas penyerapan air yang terganggu. Tanaman menunjukkan kurangnya vigor secara umum, tampak lemah dan tidak sehat. Pada bibit persemaian, infeksi parah dapat menyebabkan kematian bibit. Bibit yang terpengaruh mudah dicabut dari tanah karena penahan akar yang buruk. Laju pertumbuhan berkurang secara signifikan dibanding bibit sehat.\r\n\r\nDiagnosis memerlukan pemeriksaan sistem akar. Gali dengan hati-hati untuk menjaga akar. Cuci akar dengan lembut dan amati pewarnaan dan integritas. Akar yang sakit menunjukkan perubahan warna khas merah hingga coklat, tekstur lunak, dan pengelupasan korteks. Pada kasus lanjut, sebagian besar akar yang tersisa adalah akar gelap yang membusuk dengan sedikit ujung akar putih yang sehat. Konfirmasi laboratorium melalui isolasi Pythium pada media selektif mungkin diperlukan untuk diagnosis definitif dibanding patogen busuk akar lainnya. Pemeriksaan mikroskopis menunjukkan struktur Pythium khas seperti sporangium dan zoospora.', 'Pengendalian busuk akar merah terutama fokus pada pencegahan melalui manajemen lingkungan dan praktik budidaya karena perlakuan kuratif setelah infeksi terbentuk sangat terbatas dalam efektivitas. Perbaikan drainase adalah tindakan pengendalian tunggal paling penting. Pada persemaian, pastikan bedengan ditinggikan untuk mencegah genangan air. Pasang sistem drainase yang memadai dengan grading yang tepat untuk pembuangan air cepat. Pada penanaman lapangan, bangun jaringan drainase komprehensif dengan saluran primer, sekunder, dan tersier yang berukuran memadai dan terpelihara.\r\n\r\nHindari penyiraman berlebihan baik dari hujan atau irigasi. Pada persemaian, terapkan rezim irigasi terkontrol dengan membiarkan tanah mengering sebagian di antara penyiraman. Siram pada pagi hari untuk memungkinkan kelembaban permukaan berlebih menguap. Gunakan media tanam dengan drainase baik dan porositas bagus untuk bibit persemaian. Campuran yang direkomendasikan mencakup kombinasi tanah atas, pasir, kompos dalam proporsi yang memberikan retensi air dan drainase. Hindari tanah liat murni atau tanah berat.\r\n\r\nPerbaikan aerasi tanah melalui penghindaran pemadatan. Minimalkan lalu lintas kendaraan terutama pada kondisi basah. Pengolahan dalam atau pembajakan bawah dapat memecah lapisan padat meningkatkan penetrasi akar dan drainase. Penambahan bahan organik seperti kompos atau TKS meningkatkan struktur dan aerasi tanah dalam tanah berat. Bedengan atau gundukan untuk penanaman pada lokasi dengan drainase buruk meninggikan zona akar di atas lapisan jenuh.\r\n\r\nPengendalian kimia dengan fungisida memiliki kegunaan terbatas karena kesulitan dalam mencapai cakupan memadai seluruh sistem akar dalam lingkungan tanah. Fungisida berbahan aktif metalaksil atau mefenoksam yang spesifik untuk oomycetes dapat diaplikasikan sebagai kocoran tanah pada bibit persemaian atau sawit muda yang menunjukkan gejala awal. Dosis biasanya 2-3 gram per liter dengan volume yang memadai untuk menembus zona akar (2-5 liter per bibit tergantung ukuran). Aplikasi ulang mungkin diperlukan setiap 2-4 minggu.\r\n\r\nPengendalian biologis menggunakan mikroorganisme antagonis menunjukkan harapan. Trichoderma spp., Gliocladium spp., dan Bacillus spp. tertentu dapat menekan Pythium melalui kompetisi, antibiosis, dan mikoparasitisme. Aplikasi bio-fungisida pada media tanam atau tanah di sekitar bibit dapat memberikan perlindungan. Beberapa aplikasi biasanya diperlukan untuk membangun populasi yang memadai. Menggabungkan agen bio-kontrol dengan praktik budidaya yang baik memberikan pendekatan terpadu.\r\n\r\nTindakan sanitasi penting. Gunakan bahan tanam bebas patogen. Pastikan media persemaian steril atau dipasteurisasi sebelum digunakan. Disinfeksi alat, wadah, dan peralatan dengan natrium hipoklorit atau senyawa amonium kuaterner. Hindari menggunakan air dari sumber yang berpotensi terkontaminasi untuk irigasi. Terapkan protokol kebersihan ketat dalam operasi persemaian. Isolasi bibit yang diduga terinfeksi segera untuk mencegah penyebaran.\r\n\r\nSeleksi bahan tanam yang tahan atau toleran jika variabilitas dalam kerentanan teridentifikasi. Pantau persemaian dan perkebunan muda secara teratur untuk deteksi dini. Buang dan musnahkan bibit yang terinfeksi parah. Perlakuan paling efektif saat infeksi terdeteksi dini sebelum kerusakan sistem akar ekstensif terjadi. Pertahankan nutrisi tanaman optimal untuk mendukung pertumbuhan akar yang kuat dan mengkompensasi beberapa kehilangan akar. Fosfor yang memadai sangat penting untuk perkembangan akar.', 'b4988d965f1ee0c5f83b6d5264e3472f.jpeg');
INSERT INTO `jenis_penyakit` (`id_penyakit`, `nama_penyakit`, `penyebab`, `gejala`, `cara_pengendalian`, `gambar_ilustrasi`) VALUES
(17, 'Penyakit Layu Bakteri', 'Penyakit layu bakteri disebabkan oleh bakteri Ralstonia solanacearum (sebelumnya Pseudomonas solanacearum) yang merupakan patogen bakteri tular tanah dengan kisaran inang sangat luas meliputi ratusan spesies tanaman dari banyak famili. R. solanacearum adalah bakteri gram-negatif yang menginvasi sistem pembuluh tanaman menyebabkan layu bakteri. Bakteri memiliki struktur populasi kompleks dengan ras, biovar, dan filotipe berbeda yang bervariasi dalam kisaran inang dan distribusi geografis.\r\n\r\nInfeksi terjadi melalui akar, biasanya masuk melalui luka atau bukaan alami seperti titik munculnya akar. Bakteri dapat bertahan dalam tanah untuk periode yang lama, terutama dalam asosiasi dengan akar inang atau gulma. Dalam pembuluh xilem, bakteri berkembang biak dengan cepat membentuk biofilm dan menghasilkan polisakarida ekstraselular (EPS) yang terakumulasi secara masif dan secara fisik menghalangi transportasi air. Disfungsi pembuluh diperburuk oleh respons pertahanan inang seperti pembentukan tilosis dan produksi getah.\r\n\r\nPerkembangan penyakit sangat dipengaruhi oleh faktor lingkungan. Suhu tinggi (28-35°C) mendukung perkembangan bakteri dan ekspresi gejala. Kelembaban tanah tinggi dari curah hujan deras atau irigasi berlebihan mempromosikan penyebaran dan infeksi bakteri. Tanah asam (pH 5,0-6,0) umumnya lebih kondusif dibanding tanah netral atau basa. Luka pada akar dari nematoda, serangga, praktik budidaya, atau transplantasi memberikan titik masuk. Penyakit dapat dimasukkan melalui bahan tanam terinfeksi, air terkontaminasi, atau tanah yang terinfestasi. Penyebaran dalam perkebunan terjadi melalui pergerakan air, alat, dan mungkin vektor serangga.', 'Gejala khas adalah layu mendadak pada daun dan pelepah meskipun kelembaban tanah memadai. Layu biasanya dimulai dengan beberapa pelepah menunjukkan kehilangan turgor, terkulai, dan epinasti (pembengkokan ke bawah). Pelepah yang terpengaruh awalnya layu selama bagian terpanas hari dan mungkin pulih sebagian di malam hari, tetapi secara progresif gagal pulih seiring penyakit berkembang. Layu menyebar ke pelepah tambahan dan akhirnya seluruh tajuk terpengaruh.\r\n\r\nDaun berubah kuning atau klorosis sebelum layu. Nekrosis atau pencoklatan tepi dan ujung daun dapat terjadi. Pada bibit atau sawit muda, layu dapat menyebabkan keruntuhan total dan kematian dalam beberapa hari hingga minggu. Sawit dewasa mungkin menunjukkan perkembangan lebih lambat tetapi penurunan akhirnya tidak dapat dihindari tanpa intervensi.\r\n\r\nGejala internal bersifat diagnostik. Ketika batang atau tangkai daun dipotong melintang, perubahan warna pembuluh terlihat sebagai garis coklat atau abu-abu kecoklatan dalam xilem. Jika batang yang dipotong ditekan atau diperas dengan lembut, rembesan bakteri atau cairan kental putih hingga keabu-abuan keluar dari berkas pembuluh. Ini adalah aliran bakteri dalam matriks EPS, sangat diagnostik untuk layu bakteri. Tes dapat dilakukan dengan menempatkan batang yang dipotong dalam air bening - aliran bakteri terlihat sebagai aliran keruh yang keluar dari permukaan potongan.\r\n\r\nPemeriksaan sistem akar menunjukkan pencoklatan atau nekrosis jaringan pembuluh. Akar lateral mungkin menunjukkan lesi coklat lokal pada lokasi infeksi. Tahap lanjut menampilkan pembusukan sistem akar yang ekstensif. Di atas tanah, tanaman menunjukkan penampilan kerdil secara keseluruhan, vigor berkurang, dan gugur daun prematur. Pembungaan dan produksi buah sangat terganggu atau sepenuhnya berhenti. Sawit yang terpengaruh akhirnya mati jika penyakit tidak dikendalikan, meskipun garis waktunya bervariasi.\r\n\r\nDiagnosis diferensial penting karena gejala layu dapat disebabkan oleh berbagai faktor. Fitur kunci yang membedakan untuk layu bakteri adalah: onset mendadak, perubahan warna pembuluh, aliran bakteri dari batang yang dipotong, dan perkembangan meskipun kelembaban tanah memadai. Konfirmasi laboratorium melalui isolasi patogen pada media selektif dan tes identifikasi biokimia atau molekuler memberikan diagnosis definitif.', 'Pengendalian layu bakteri sangat menantang karena bakteri berada terlindungi dalam sistem pembuluh dan dapat bertahan dalam tanah. Pendekatan terpadu penting menggabungkan pencegahan, praktik budidaya, dan perlakuan terapeutik. Pencegahan sangat penting karena infeksi yang sudah terbentuk sulit disembuhkan. Gunakan bahan tanam bersertifikat bebas penyakit dari sumber terpercaya. Periksa bibit dengan hati-hati untuk gejala sebelum penanaman. Tolak material yang mencurigakan.\r\n\r\nPemilihan lokasi dengan menghindari area dengan riwayat layu bakteri yang diketahui atau dengan tanaman rentan sebelumnya. Jika tidak dapat dihindari, terapkan perlakuan tanah sebelum penanaman. Solarisasi tanah selama periode kering panas dapat mengurangi populasi bakteri. Penggenangan untuk kondisi anaerobik (jika memungkinkan) juga menekan. Fumigasi tanah kimia dengan produk seperti metam natrium dapat efektif tetapi mahal dan menimbulkan kekhawatiran lingkungan.\r\n\r\nPenanaman varietas tahan adalah solusi ideal tetapi bahan tersebut untuk kelapa sawit umumnya tidak tersedia atau tidak cukup terkarakterisasi. Penelitian tentang pemuliaan ketahanan sedang berlangsung. Sementara itu, fokus pada meminimalkan tekanan penyakit dan menjaga kesehatan tanaman. Sanitasi penting untuk mencegah introduksi dan penyebaran. Disinfeksi semua alat, peralatan, dan mesin secara teratur dengan natrium hipoklorit (2%) atau desinfektan amonium kuaterner. Terutama penting setelah bekerja pada tanaman terinfeksi.\r\n\r\nMinimalkan pelukaan akar dan batang selama budidaya, penyiangan, pemupukan, atau operasi lainnya. Hindari pengolahan dalam yang merusak akar. Kendalikan nematoda dan serangga perusak akar yang menciptakan titik masuk. Terapkan praktik konservasi tanah untuk mencegah erosi dan paparan akar. Manajemen air dengan menghindari irigasi berlebihan atau genangan air. Gunakan irigasi tetes lebih disukai daripada irigasi banjir untuk mengurangi penyebaran bakteri melalui air.\r\n\r\nUntuk sawit terinfeksi yang terdeteksi dini, perlakuan terapeutik agresif dapat dicoba meskipun tingkat keberhasilan bervariasi. Bakterisida atau antibiotik yang terdaftar untuk penggunaan pertanian seperti streptomisin atau oksitetrasiklin dapat diaplikasikan sebagai injeksi batang atau kocoran tanah. Dosis dan protokol mengikuti rekomendasi label. Beberapa aplikasi biasanya diperlukan. Efektivitas terbatas dan mahal, praktis terutama untuk sawit individual bernilai tinggi.\r\n\r\nPendekatan biokontrol sedang dalam pengembangan. Bakteri antagonis seperti Bacillus spp. atau Pseudomonas fluorescens yang menghasilkan antibiotik atau bersaing dengan patogen menunjukkan potensi. Aplikasi pada tanah atau sebagai perlakuan bibit. Produk komersial semakin tersedia. Gabungkan dengan kontrol budidaya untuk program terpadu.\r\n\r\nRotasi dengan tanaman bukan inang jika memungkinkan mengurangi inokulum tanah seiring waktu. Banyak tanaman dari famili rumput adalah bukan inang. Bera berkepanjangan juga mengurangi populasi. Amandemen tanah dengan bahan organik tertentu atau kapur yang meningkatkan pH dapat menciptakan kondisi yang kurang menguntungkan. Eradikasi sawit terinfeksi penting untuk mengurangi inokulum. Buang seluruh tanaman termasuk sistem akar dengan hati-hati untuk menghindari penyebaran tanah terkontaminasi. Musnahkan material terinfeksi dengan membakar atau mengubur dalam. Perlakukan tanah dalam lubang tanam dengan desinfektan sebelum penanaman ulang.\r\n\r\nProgram pemantauan untuk deteksi dini memungkinkan tindakan segera. Inspeksi rutin untuk tanaman yang layu terutama selama cuaca panas. Selidiki layu yang tidak dapat dijelaskan. Pengujian cepat dengan tes aliran bakteri memberikan diagnosis lapangan cepat. Isolasi area yang terpengaruh dengan penghalang atau parit untuk menghambat penyebaran. Terapkan protokol kebersihan ketat dalam blok yang terpengaruh. Manajemen penyakit terpadu yang menggabungkan semua taktik yang tersedia menawarkan peluang terbaik untuk meminimalkan dampak penyakit serius ini.', '9c1e2cca24f366b6934154be4ee64122.jpg'),
(18, 'Penyakit Bercak Hitam Tandan', 'Penyakit bercak hitam tandan disebabkan oleh jamur Alternaria spp. yang merupakan hyphomycetes berselaput gelap dengan distribusi di seluruh dunia. Alternaria adalah genus besar yang berisi banyak spesies, beberapa diantaranya patogen tanaman sementara yang lain saprofit. Pada tandan kelapa sawit, spesies Alternaria yang terlibat mungkin termasuk A. alternata dan spesies terkait. Jamur menghasilkan konidia berwarna gelap multiseluler dalam rantai yang khas untuk genus.\r\n\r\nInfeksi terjadi ketika konidia yang disebarkan oleh angin atau percikan hujan mendarat pada permukaan tandan, terutama pada bunga atau buah muda yang sedang berkembang. Perkecambahan memerlukan kelembaban bebas dan suhu dalam kisaran 15-30°C. Tabung kecambah menembus langsung melalui kutikula atau masuk melalui luka atau bukaan alami. Hifa berkembang dalam jaringan buah, menghasilkan enzim dan toksin yang menyebabkan kematian sel dan nekrosis. Jaringan terinfeksi berubah coklat gelap hingga hitam dari struktur jamur yang termelanisasi.\r\n\r\nPenyakit disukai oleh kelembaban tinggi, basah berkepanjangan pada permukaan tandan dari curah hujan sering atau embun deras, suhu sedang, dan faktor apa pun yang mengkompromikan integritas buah seperti kerusakan serangga, gangguan fisiologis, atau ketidakseimbangan nutrisi. Defisiensi Kalium terutama membuat buah rentan terhadap infeksi dengan melemahkan dinding buah. Alternaria sering dianggap sebagai penyerang sekunder atau patogen oportunistik, mengkolonisasi jaringan yang sudah lemah atau rusak oleh faktor lain. Namun, pada kondisi yang menguntungkan dapat menyebabkan infeksi primer terutama pada tanaman yang stres. Kejadian penyakit sering berkorelasi dengan musim basah dan area dengan sirkulasi udara buruk.', 'Gejala karakteristik adalah munculnya bercak hitam atau bintik gelap pada permukaan buah individual dalam tandan dan kadang pada rakis atau tangkai tandan. Bintik awalnya kecil (diameter 2-5 mm), melingkar hingga tidak beraturan, berwarna coklat gelap hingga hitam. Lesi mungkin memiliki penampilan sedikit cekung atau tertekan. Pada kondisi lembab, pertumbuhan berbulu hijau zaitun gelap hingga hitam terlihat pada permukaan lesi mewakili sporulasi jamur.\r\n\r\nLesi meluas seiring waktu, bintik individual membesar dan bintik yang berdekatan menyatu membentuk area nekrotik tidak beraturan yang lebih besar. Perkembangan lesi ekstensif menyebabkan penggelapan permukaan buah yang signifikan. Buah terinfeksi mungkin menunjukkan pelunakan atau kerusakan jaringan, menjadi lembek terutama dengan invasi bakteri sekunder. Bau tidak sedap dapat keluar dari jaringan yang membusuk. Gugur buah prematur atau absisi meningkat, dengan buah terinfeksi terlepas dari tandan sebelum waktunya.\r\n\r\nPada infeksi parah, bagian substansial buah dalam tandan terpengaruh, mengurangi hasil dan kualitas yang dapat dipanen. Tandan dengan persentase tinggi buah yang sakit sering dipanen prematur atau diturunkan kualitasnya di pabrik. Kualitas minyak terganggu dengan tingkat Asam Lemak Bebas (ALB) yang meningkat terkait dengan degradasi buah. Perkembangan kernel dapat terganggu dalam buah yang terpengaruh parah. Dampak penyakit bervariasi secara musiman, biasanya mencapai puncak selama periode basah yang diperpanjang dengan kelembaban tinggi.\r\n\r\nGejala harus dibedakan dari gangguan tandan lainnya seperti busuk tandan Marasmius (yang biasanya menunjukkan pertumbuhan miselium putih), partenokarpi (yang menghasilkan buah kecil tanpa biji tanpa lesi eksternal), atau bercak fisiologis dari ketidakseimbangan nutrisi (yang umumnya tidak memiliki pertumbuhan jamur). Pemeriksaan laboratorium struktur jamur memberikan diagnosis konfirmasi. Konidia Alternaria khas dengan bentuk obklavat, warna coklat gelap, beberapa septa transversal dan longitudinal menciptakan penampilan muriform.', 'Pengendalian bercak hitam tandan memerlukan pendekatan manajemen terpadu. Aplikasi fungisida adalah metode pengendalian utama terutama selama periode tekanan penyakit tinggi. Fungisida berbahan aktif iprodion, klorotalonil, mankozeb, atau senyawa tembaga efektif melawan Alternaria. Dosis biasanya 2-3 gram per liter. Aplikasi ditargetkan pada bunga dan tandan yang sedang berkembang pada tahap kritis: (1) selama antesis, (2) 4-6 minggu pasca-antesis, dan (3) semprot tambahan selama periode basah berkepanjangan.\r\n\r\nWaktu sangat penting - aplikasi preventif sebelum infeksi terjadi lebih efektif dibanding perlakuan kuratif setelah penyakit terbentuk. Cakupan semprot harus menyeluruh untuk mencapai bunga dan buah di seluruh tandan. Penyemprotan volume tinggi dengan tekanan yang memadai diperlukan. Rotasi bahan aktif fungisida dari kelompok kimia berbeda untuk mencegah perkembangan resistensi. Ajuvan atau perekat-penyebar meningkatkan cakupan dan ketahanan hujan.\r\n\r\nPraktik budidaya fokus pada mengurangi kelembaban di zona tandan dan meningkatkan kesehatan tanaman. Pemangkasan untuk meningkatkan sirkulasi udara dan penetrasi cahaya di sekitar tandan. Buang pertumbuhan vegetatif berlebihan yang menjebak kelembaban. Pertahankan jumlah pelepah optimal - kanopi yang terlalu lebat menghambat pergerakan udara dan pengeringan setelah hujan. Jarak yang tepat saat penanaman penting untuk sirkulasi udara jangka panjang. Hindari kepadatan berlebih.\r\n\r\nManajemen nutrisi sangat penting. Pemupukan Kalium yang memadai penting untuk kekuatan dinding buah dan ketahanan penyakit. Dosis yang direkomendasikan biasanya 2,5-3 kg KCl per sawit dewasa per tahun, disesuaikan berdasarkan analisis daun. Perbaiki defisiensi Kalium dengan segera melalui aplikasi tanah dan daun. Kecukupan Boron juga penting untuk integritas buah. Nutrisi seimbang secara keseluruhan mendukung vigor tanaman dan kualitas buah.\r\n\r\nManajemen air pada perkebunan beririgasi dengan menghindari metode di atas yang membasahi tandan. Gunakan sistem irigasi lokal. Waktu irigasi untuk pagi hari untuk memungkinkan pengeringan cepat. Pastikan drainase yang baik untuk mencegah genangan air yang meningkatkan kelembaban atmosfer. Praktik panen dengan mempertahankan ronde yang tepat untuk mencegah kematangan berlebih yang meningkatkan kerentanan. Panen tandan terinfeksi dengan segera dan proses secara terpisah.\r\n\r\nSanitasi dengan membuang material terinfeksi dari titik pengumpulan dan jalan lapangan. Jangan biarkan akumulasi tandan yang sakit yang berfungsi sebagai sumber inokulum. Pengendalian hama serangga terutama serangga pemakan tandan atau penggerek yang menciptakan luka yang memfasilitasi masuknya jamur. Program manajemen hama terpadu yang mengatasi masalah serangga berkontribusi pada pengurangan penyakit.\r\n\r\nSeleksi genetik jika informasi tersedia mengenai arsitektur tandan atau karakteristik buah yang terkait dengan ketahanan lebih baik atau kondisi yang kurang menguntungkan untuk infeksi. Beberapa jenis tandan dengan kemasan buah yang lebih longgar dapat memungkinkan sirkulasi udara lebih baik dan pengeringan lebih cepat. Pemantauan prakiraan cuaca untuk mengantisipasi periode berisiko tinggi. Intensifkan pengawasan dan tindakan pencegahan selama periode basah yang diperpanjang yang diprediksi. Pencatatan pola kejadian penyakit membantu mengoptimalkan waktu dan penargetan intervensi. Manajemen penyakit terpadu yang menggabungkan semua komponen ini memberikan pendekatan paling efektif untuk meminimalkan kerugian dari penyakit ini.', '773a363f49f87de67ab5fb755eea7ee5.jpeg');

